/* ============================================================
   TATOOINE OUTPOST — layout & interface
   Landscape-first, touch-first tower defense
   ============================================================ */

:root {
  --ink: #110e0a;
  --panel: #171410;
  --panel-2: #1f1a14;
  --panel-3: #292219;
  --line: rgba(241, 199, 111, 0.16);
  --line-strong: rgba(241, 199, 111, 0.34);
  --gold: #f1c76f;
  --gold-bright: #ffdf95;
  --amber: #e7a33c;
  --sand: #d9b37a;
  --text: #e9dec9;
  --muted: #a7987e;
  --cyan: #67d9f5;
  --red: #ff6b5f;
  --green: #8bd46b;
  --shop-w: clamp(198px, 21vw, 272px);
  --font-ui: "Trebuchet MS", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-head: "Arial Narrow", "Roboto Condensed", "Trebuchet MS", sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0b0906;
  color: var(--text);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
  user-select: none;
}
body { touch-action: none; }
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; touch-action: manipulation; }
button:focus-visible { outline: 2px solid var(--gold-bright); outline-offset: 2px; }
svg { display: block; }
.hidden { display: none !important; }

/* ---------- app shell ---------- */
.app {
  display: flex;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  background: #0b0906;
}

.stage {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  overflow: hidden;
  background: #b88a54;
  isolation: isolate;
}
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

/* ---------- top HUD ---------- */
.hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 6;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  pointer-events: none;
}
.hud-left {
  background: linear-gradient(180deg, rgba(18, 14, 10, 0.78), rgba(18, 14, 10, 0.48));
  border: 1px solid rgba(247, 207, 126, 0.23);
  border-radius: 9px;
  padding: 7px 11px 8px;
  min-width: 152px;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.24);
  backdrop-filter: blur(7px);
}
.map-name {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.19em;
  color: var(--muted);
  text-transform: uppercase;
  margin-bottom: 2px;
}
.map-name .dot {
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 7px var(--green);
}
.wave-line {
  display: flex;
  align-items: baseline;
  gap: 7px;
  white-space: nowrap;
}
#waveTag {
  font-family: var(--font-head);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--gold-bright);
}
#waveTag i { font-style: normal; font-size: 9px; color: var(--muted); letter-spacing: 0.05em; }
.wave-sub {
  font-size: 8.5px;
  letter-spacing: 0.08em;
  color: var(--muted);
  text-transform: uppercase;
}
.wave-track {
  height: 2px;
  margin-top: 5px;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 2px;
  overflow: hidden;
}
.wave-track i {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--amber), var(--gold-bright));
  transition: width 0.25s ease-out;
}
.hud-right {
  display: flex;
  gap: 6px;
  pointer-events: auto;
}
.icon-btn {
  width: 37px;
  height: 37px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  color: var(--text);
  border: 1px solid rgba(247, 207, 126, 0.24);
  background: linear-gradient(180deg, rgba(32, 26, 19, 0.88), rgba(16, 13, 9, 0.82));
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(7px);
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}
.icon-btn:hover { background: rgba(52, 41, 28, 0.92); border-color: var(--line-strong); }
.icon-btn:active { transform: scale(0.94); }
.icon-btn svg { width: 18px; height: 18px; fill: currentColor; }
.icon-btn .ico-muted { display: none; }
body.muted .icon-btn .ico-sound { display: none; }
body.muted .icon-btn .ico-muted { display: block; }
.speed-btn {
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 800;
  color: var(--gold-bright);
  letter-spacing: 0.03em;
}
.speed-btn.on { color: #20180d; background: linear-gradient(180deg, #f6cf7d, #dda23d); border-color: #ffe6a9; }
#btnPause.paused { color: #20180d; background: linear-gradient(180deg, #f6cf7d, #dda23d); border-color: #ffe6a9; }

/* boss bar */
.bossbar {
  position: absolute;
  z-index: 7;
  top: 58px;
  left: 50%;
  transform: translateX(-50%);
  width: min(340px, 54%);
  padding: 5px 9px 7px;
  background: rgba(19, 13, 9, 0.8);
  border: 1px solid rgba(255, 104, 84, 0.4);
  border-radius: 7px;
  backdrop-filter: blur(6px);
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.3);
}
.bossbar-top {
  display: flex;
  justify-content: space-between;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: #ffb09c;
  margin-bottom: 4px;
}
.bossbar-track { height: 5px; background: rgba(255, 255, 255, 0.12); border-radius: 3px; overflow: hidden; }
.bossbar-track i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #ad2b2b, #ff7659, #ffc46d); transition: width 0.16s linear; }

/* toasts */
.toasts {
  position: absolute;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%);
  z-index: 12;
  display: flex;
  flex-direction: column-reverse;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  max-width: min(420px, 86%);
}
.toast {
  padding: 7px 13px;
  border-radius: 20px;
  background: rgba(20, 15, 10, 0.9);
  border: 1px solid var(--line-strong);
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.35);
  animation: toast-in 0.25s cubic-bezier(0.2, 0.9, 0.3, 1.2);
  white-space: nowrap;
  backdrop-filter: blur(6px);
}
.toast.bad { border-color: rgba(255, 104, 84, 0.5); color: #ffc4b8; }
.toast.good { border-color: rgba(247, 207, 126, 0.5); color: var(--gold-bright); }
.toast.out { animation: toast-out 0.3s ease forwards; }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px) scale(0.94); } }
@keyframes toast-out { to { opacity: 0; transform: translateY(-5px) scale(0.97); } }

/* placement hint */
.place-hint {
  position: absolute;
  z-index: 8;
  left: 50%;
  bottom: 16px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 8px 7px 12px;
  border-radius: 22px;
  background: rgba(20, 15, 10, 0.92);
  border: 1px solid var(--line-strong);
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.3);
  font-size: 11px;
  color: var(--text);
  backdrop-filter: blur(6px);
  pointer-events: auto;
  white-space: nowrap;
}
.hint-pulse {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 0 0 rgba(247, 207, 126, 0.5);
  animation: pulse-dot 1.4s infinite;
}
@keyframes pulse-dot { 70% { box-shadow: 0 0 0 7px rgba(247, 207, 126, 0); } 100% { box-shadow: 0 0 0 0 rgba(247, 207, 126, 0); } }
.place-hint button {
  width: 24px; height: 24px; border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  color: var(--muted);
  font-size: 16px;
  line-height: 1;
  display: grid; place-items: center;
}
.place-hint button:hover { background: rgba(255, 255, 255, 0.16); color: var(--text); }

/* ---------- sidebar ---------- */
.shop {
  position: relative;
  z-index: 20;
  flex: 0 0 var(--shop-w);
  width: var(--shop-w);
  height: 100%;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(120% 60% at 100% 0%, rgba(128, 88, 38, 0.16), transparent 60%),
    linear-gradient(180deg, #1d1812 0%, #15120e 55%, #100e0a 100%);
  border-left: 1px solid rgba(241, 199, 111, 0.23);
  box-shadow: -10px 0 30px rgba(0, 0, 0, 0.25);
  padding-right: env(safe-area-inset-right);
  padding-bottom: env(safe-area-inset-bottom);
}
.shop::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.55;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.018) 1px, transparent 1px);
  background-size: 22px 22px;
  mask-image: linear-gradient(180deg, #000 0%, transparent 48%);
}
.shop-head {
  position: relative;
  flex: 0 0 auto;
  padding: 11px 11px 9px;
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: 8px; }
.brand-mark {
  width: 26px; height: 26px;
  color: var(--gold);
  filter: drop-shadow(0 0 7px rgba(241, 199, 111, 0.3));
  flex: 0 0 auto;
}
.brand-mark svg { width: 100%; height: 100%; }
.brand-kicker {
  font-size: 6.5px;
  letter-spacing: 0.22em;
  color: var(--muted);
  font-weight: 700;
  line-height: 1.2;
}
.brand-name {
  font-family: var(--font-head);
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.16em;
  line-height: 1.05;
  color: var(--gold-bright);
  text-shadow: 0 0 16px rgba(241, 199, 111, 0.16);
}
.stats {
  display: flex;
  gap: 6px;
  margin-top: 9px;
}
.stat {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1;
  min-width: 0;
  padding: 5px 7px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.055);
  font-family: var(--font-head);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.stat svg { width: 15px; height: 15px; flex: 0 0 auto; }
.credit-stat svg { color: var(--gold); }
.life-stat { color: #ffb6a8; }
.life-stat svg { color: var(--red); }
.stat.bump { animation: stat-bump 0.22s ease; }
@keyframes stat-bump { 50% { transform: scale(1.08); } }

.shop-body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.build-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1;
}
.panel-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 11px 6px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--muted);
}
.panel-title .panel-hint {
  font-size: 6.5px;
  letter-spacing: 0.13em;
  color: rgba(167, 152, 126, 0.62);
}
.tower-list {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-auto-rows: min-content;
  gap: 6px;
  padding: 0 9px 9px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(241, 199, 111, 0.2) transparent;
}
.tower-list::-webkit-scrollbar { width: 4px; }
.tower-list::-webkit-scrollbar-thumb { background: rgba(241, 199, 111, 0.22); border-radius: 3px; }

.tower-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-height: 72px;
  padding: 7px 4px 6px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.075);
  background:
    radial-gradient(120% 80% at 50% 0%, rgba(255, 255, 255, 0.045), transparent 70%),
    linear-gradient(180deg, #282119, #1c1711);
  color: var(--text);
  transition: transform 0.12s ease, border-color 0.15s, background 0.15s, box-shadow 0.15s;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045), 0 2px 6px rgba(0, 0, 0, 0.16);
  overflow: hidden;
  touch-action: none;
}
.tower-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 55%, rgba(0, 0, 0, 0.18));
  pointer-events: none;
}
.tower-card:hover { border-color: rgba(241, 199, 111, 0.34); background: linear-gradient(180deg, #32291e, #211b14); transform: translateY(-1px); }
.tower-card:active { transform: scale(0.97); }
.tower-card.poor { opacity: 0.48; filter: saturate(0.65); }
.tower-card.poor .cost { color: #ff9a8c; }
.tower-card.armed {
  border-color: var(--gold);
  background: linear-gradient(180deg, #3d301e, #241c12);
  box-shadow: 0 0 0 1px rgba(241, 199, 111, 0.22), 0 0 18px rgba(241, 199, 111, 0.16);
}
.tower-card.dragging { opacity: 0.28; }
.tower-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  color: var(--gold);
  border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, rgba(255, 255, 255, 0.09), rgba(0, 0, 0, 0.1) 70%);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}
.tower-icon svg { width: 31px; height: 31px; overflow: visible; }
.tower-name {
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0.02em;
  color: #e7dcc6;
  text-align: center;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cost {
  display: flex;
  align-items: center;
  gap: 2px;
  font-family: var(--font-head);
  font-size: 11px;
  font-weight: 800;
  color: var(--gold-bright);
  font-variant-numeric: tabular-nums;
}
.cost svg { width: 9px; height: 9px; opacity: 0.8; }
.hotkey {
  position: absolute;
  top: 3px;
  left: 4px;
  font-size: 7px;
  color: rgba(233, 222, 201, 0.35);
  font-weight: 700;
  letter-spacing: 0.04em;
}
.lock-badge {
  position: absolute; top: 4px; right: 4px;
  font-size: 6px; font-weight: 800; letter-spacing: 0.08em;
  color: #ffbfae; background: rgba(116, 33, 24, 0.6);
  padding: 2px 3px; border-radius: 3px;
}

/* inspection panel */
.inspect-panel {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  flex-direction: column;
  padding: 10px;
  background:
    radial-gradient(120% 50% at 100% 0%, rgba(128, 88, 38, 0.2), transparent 65%),
    linear-gradient(180deg, #1e1912, #13100c);
  overflow-y: auto;
  scrollbar-width: thin;
  animation: inspect-in 0.18s ease-out;
}
@keyframes inspect-in { from { opacity: 0; transform: translateX(12px); } }
.inspect-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}
.inspect-icon {
  width: 44px; height: 44px; flex: 0 0 auto;
  display: grid; place-items: center;
  border-radius: 9px;
  background: radial-gradient(circle at 50% 35%, rgba(241, 199, 111, 0.16), rgba(0, 0, 0, 0.22));
  border: 1px solid rgba(241, 199, 111, 0.2);
  color: var(--gold);
}
.inspect-icon svg { width: 34px; height: 34px; }
.inspect-title { flex: 1; min-width: 0; }
#inspectName {
  font-family: var(--font-head);
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.04em;
  line-height: 1.1;
  color: var(--gold-bright);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.level-line {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--muted);
  margin-top: 3px;
}
.close-btn {
  width: 27px; height: 27px;
  border-radius: 50%;
  display: grid; place-items: center;
  font-size: 18px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.055);
  line-height: 1;
}
.close-btn:hover { background: rgba(255, 255, 255, 0.12); color: var(--text); }
.inspect-desc {
  margin: 8px 1px 9px;
  font-size: 9.5px;
  line-height: 1.45;
  color: var(--muted);
}
.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  margin-bottom: 7px;
}
.stat-grid > div {
  padding: 5px 6px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.05);
}
.stat-grid span {
  display: block;
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: var(--muted);
  margin-bottom: 1px;
}
.stat-grid b {
  font-family: var(--font-head);
  font-size: 13px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.target-btn {
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  padding: 6px 8px;
  margin-bottom: 6px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.035);
  text-align: left;
}
.target-btn:hover { border-color: var(--line-strong); }
.target-btn span { font-size: 6.5px; font-weight: 800; letter-spacing: 0.16em; color: var(--muted); flex: 1; }
.target-btn b { font-family: var(--font-head); font-size: 10px; letter-spacing: 0.08em; color: var(--gold); }
.target-btn svg { width: 14px; height: 14px; color: var(--muted); }

.upgrade-btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  width: 100%;
  padding: 8px 9px;
  border-radius: 7px;
  border: 1px solid rgba(241, 199, 111, 0.36);
  background:
    radial-gradient(120% 100% at 0 0%, rgba(255, 222, 145, 0.13), transparent 60%),
    linear-gradient(180deg, #3a2e1d, #241c12);
  text-align: left;
  transition: border-color 0.15s, filter 0.15s, transform 0.1s;
}
.upgrade-btn:hover { border-color: var(--gold); filter: brightness(1.1); }
.upgrade-btn:active { transform: scale(0.985); }
.upgrade-btn.disabled { opacity: 0.42; filter: saturate(0.55); pointer-events: none; }
.upgrade-btn.maxed { border-color: rgba(255, 255, 255, 0.1); background: rgba(255, 255, 255, 0.035); pointer-events: none; }
.up-label { font-size: 7px; font-weight: 800; letter-spacing: 0.17em; color: var(--gold); }
.up-cost {
  display: flex; align-items: center; gap: 3px;
  font-family: var(--font-head);
  font-size: 15px; font-weight: 900; color: var(--gold-bright);
  font-variant-numeric: tabular-nums;
}
.up-cost svg { width: 12px; height: 12px; }
.up-delta { font-size: 7px; letter-spacing: 0.05em; color: #a5ce84; font-weight: 700; }
.sell-btn {
  margin-top: 6px;
  padding: 6px;
  width: 100%;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.055);
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.15em;
  background: rgba(255, 255, 255, 0.025);
}
.sell-btn span { color: #ddc79b; }
.sell-btn:hover { color: #ffc4b8; border-color: rgba(255, 104, 84, 0.3); background: rgba(255, 104, 84, 0.055); }

/* shop footer / wave button */
.shop-foot {
  position: relative;
  flex: 0 0 auto;
  padding: 7px 9px 10px;
  border-top: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(20, 16, 12, 0.5), rgba(12, 10, 8, 0.7));
}
.wave-status {
  display: flex;
  align-items: center;
  gap: 5px;
  min-height: 18px;
  padding: 0 2px 5px;
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.035em;
  color: var(--muted);
  line-height: 1.25;
}
.status-dot {
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 6px rgba(139, 212, 107, 0.7);
  flex: 0 0 auto;
}
.wave-status.active .status-dot { background: var(--amber); box-shadow: 0 0 6px rgba(231, 163, 60, 0.8); }
.wave-status.danger .status-dot { background: var(--red); box-shadow: 0 0 6px rgba(255, 107, 95, 0.8); }
.send-btn {
  position: relative;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  padding: 9px 8px 8px;
  border-radius: 8px;
  border: 1px solid #ffe4a3;
  color: #21170b;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.32), transparent 42%),
    linear-gradient(180deg, #f3c86f, #d99a33);
  box-shadow: 0 3px 0 #8f5c1c, 0 7px 20px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  transition: filter 0.15s, transform 0.1s, box-shadow 0.1s;
  overflow: hidden;
}
.send-btn::after {
  content: "";
  position: absolute;
  top: 0; bottom: 0; width: 40%;
  left: -60%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.32), transparent);
  transform: skewX(-18deg);
  animation: sheen 3.6s ease-in-out infinite;
}
@keyframes sheen { 0%, 52% { left: -60%; } 72%, 100% { left: 130%; } }
.send-btn:hover { filter: brightness(1.06); }
.send-btn:active { transform: translateY(2px); box-shadow: 0 1px 0 #8f5c1c, 0 4px 12px rgba(0, 0, 0, 0.3); }
.send-btn span {
  font-family: var(--font-head);
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.08em;
  line-height: 1;
}
.send-btn small { font-size: 7px; font-weight: 800; letter-spacing: 0.08em; opacity: 0.68; }
.send-btn.in-wave {
  border-color: rgba(255, 255, 255, 0.12);
  color: #d8c9ad;
  background: linear-gradient(180deg, #322a20, #211b14);
  box-shadow: 0 2px 0 #0d0b08, inset 0 1px 0 rgba(255, 255, 255, 0.06);
  cursor: default;
}
.send-btn.in-wave::after { display: none; }
.send-btn.in-wave small { opacity: 0.55; }

/* ---------- drag ghost ---------- */
.drag-ghost {
  position: fixed;
  z-index: 200;
  left: 0; top: 0;
  pointer-events: none;
  transform: translate(-50%, -120%);
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 11px 6px 7px;
  border-radius: 26px;
  border: 1px solid rgba(255, 223, 149, 0.7);
  background: rgba(24, 19, 13, 0.94);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45), 0 0 0 1px rgba(0, 0, 0, 0.25);
  color: var(--gold);
  backdrop-filter: blur(8px);
}
.drag-ghost .tower-icon { width: 28px; height: 28px; background: none; box-shadow: none; }
.drag-ghost .tower-icon svg { width: 27px; height: 27px; }
.drag-ghost .ghost-name { font-size: 10px; font-weight: 800; letter-spacing: 0.04em; color: var(--text); white-space: nowrap; }
.drag-ghost .ghost-cost { font-family: var(--font-head); font-size: 12px; font-weight: 900; color: var(--gold-bright); }
.drag-ghost.bad { border-color: rgba(255, 104, 84, 0.72); }
.drag-ghost.bad .ghost-cost { color: #ff9c8d; }

/* ---------- modal ---------- */
.modal {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: grid;
  place-items: center;
  background: rgba(12, 9, 6, 0.58);
  backdrop-filter: blur(5px);
  animation: fade-in 0.2s ease;
}
@keyframes fade-in { from { opacity: 0; } }
.modal-card {
  width: min(320px, 84%);
  padding: 18px;
  border-radius: 12px;
  border: 1px solid var(--line-strong);
  background: linear-gradient(180deg, #241e16, #15110d);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  text-align: center;
}
.modal-card .eyebrow { font-size: 7px; letter-spacing: 0.24em; color: var(--gold); font-weight: 800; margin-bottom: 4px; }
.modal-card h2 { font-family: var(--font-head); font-size: 26px; letter-spacing: 0.1em; margin: 0 0 5px; color: var(--gold-bright); }
.modal-card p { margin: 0 0 14px; font-size: 10px; color: var(--muted); line-height: 1.5; }
.modal-actions { display: flex; gap: 7px; justify-content: center; flex-wrap: wrap; }
.btn-primary {
  padding: 9px 18px;
  border-radius: 7px;
  border: 1px solid #ffe4a3;
  background: linear-gradient(180deg, #f3c86f, #d99a33);
  color: #21170b;
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.09em;
  box-shadow: 0 3px 0 #8f5c1c;
}
.btn-primary:active { transform: translateY(2px); box-shadow: 0 1px 0 #8f5c1c; }
.btn-ghost {
  padding: 9px 16px;
  border-radius: 7px;
  border: 1px solid rgba(241, 199, 111, 0.28);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
  font-family: var(--font-head);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.09em;
}
.btn-ghost:hover { background: rgba(255, 255, 255, 0.09); border-color: var(--line-strong); }

/* ---------- full screens ---------- */
.screen {
  position: fixed;
  inset: 0;
  z-index: 100;
  overflow: hidden;
  background: #0a0806;
  display: flex;
  align-items: center;
  justify-content: center;
}
.stars {
  position: absolute;
  inset: -20%;
  pointer-events: none;
  background-image:
    radial-gradient(1px 1px at 12% 18%, rgba(255, 245, 220, 0.8), transparent 100%),
    radial-gradient(1px 1px at 23% 64%, rgba(255, 245, 220, 0.55), transparent 100%),
    radial-gradient(1.4px 1.4px at 38% 31%, rgba(255, 236, 201, 0.85), transparent 100%),
    radial-gradient(1px 1px at 47% 78%, rgba(255, 245, 220, 0.45), transparent 100%),
    radial-gradient(1.2px 1.2px at 61% 12%, rgba(255, 245, 220, 0.7), transparent 100%),
    radial-gradient(1px 1px at 73% 55%, rgba(255, 245, 220, 0.55), transparent 100%),
    radial-gradient(1.5px 1.5px at 84% 27%, rgba(255, 245, 220, 0.8), transparent 100%),
    radial-gradient(1px 1px at 92% 72%, rgba(255, 245, 220, 0.5), transparent 100%),
    radial-gradient(1px 1px at 6% 84%, rgba(255, 245, 220, 0.55), transparent 100%),
    radial-gradient(1px 1px at 55% 45%, rgba(255, 245, 220, 0.4), transparent 100%);
  background-size: 340px 280px;
  opacity: 0.7;
  animation: drift 60s linear infinite;
}
.stars-b { background-size: 210px 190px; opacity: 0.35; animation-duration: 95s; animation-direction: reverse; }
@keyframes drift { to { transform: translate3d(-120px, 60px, 0); } }
.start-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(90% 110% at 82% 60%, rgba(212, 133, 44, 0.18), transparent 55%),
    radial-gradient(70% 80% at 15% 20%, rgba(73, 64, 92, 0.2), transparent 70%),
    linear-gradient(100deg, #080705 0%, #0d0a07 45%, #131009 100%);
}
.planet {
  position: absolute;
  right: -9vw;
  bottom: -52vh;
  width: min(72vw, 940px);
  aspect-ratio: 1;
  border-radius: 50%;
  background:
    radial-gradient(38% 28% at 36% 30%, rgba(255, 203, 94, 0.16), transparent 55%),
    radial-gradient(circle at 42% 36%, #b1712e 0%, #7a4c24 38%, #3d2917 66%, #1a120c 82%);
  box-shadow: inset 18px 22px 80px rgba(0, 0, 0, 0.6), 0 0 100px rgba(220, 147, 51, 0.12);
  opacity: 0.9;
}
.planet::before {
  content: "";
  position: absolute;
  inset: -9% -22%;
  border-radius: 50%;
  border: 2px solid rgba(238, 193, 111, 0.12);
  border-bottom-color: rgba(238, 193, 111, 0.24);
  transform: rotate(-18deg) scaleY(0.3);
  box-shadow: 0 0 30px rgba(238, 193, 111, 0.05);
}
.planet::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background:
    linear-gradient(115deg, transparent 46%, rgba(0, 0, 0, 0.26) 47%, transparent 56%),
    repeating-linear-gradient(8deg, rgba(255, 255, 255, 0.025) 0 2px, transparent 2px 19px);
  mix-blend-mode: multiply;
}
.start-wrap {
  position: relative;
  z-index: 2;
  width: min(760px, 88vw);
  margin-right: 20vw;
  padding: 20px 0;
  animation: rise 0.7s cubic-bezier(0.16, 0.8, 0.3, 1) both;
}
@keyframes rise { from { opacity: 0; transform: translateY(18px); } }
.start-eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.34em;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 12px;
  text-shadow: 0 0 14px rgba(241, 199, 111, 0.3);
}
.start-eyebrow span { width: 28px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.start-eyebrow span:last-child { background: linear-gradient(90deg, var(--gold), transparent); }
.start-wrap h1 {
  margin: 0;
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(42px, 7vw, 88px);
  line-height: 0.83;
  letter-spacing: 0.065em;
  color: #f3ead9;
  text-shadow: 0 4px 28px rgba(0, 0, 0, 0.6);
}
.start-wrap h1 em {
  display: inline-block;
  font-style: normal;
  color: transparent;
  background: linear-gradient(180deg, #fff0bd 0%, #f2c56b 45%, #d08727 100%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 24px rgba(241, 191, 90, 0.22));
  letter-spacing: 0.11em;
}
.start-tag {
  margin: 16px 0 20px;
  max-width: 480px;
  font-size: clamp(11px, 1.1vw, 14px);
  line-height: 1.6;
  color: #b3a58d;
}
.deploy-btn {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 12px 30px 11px;
  border-radius: 8px;
  border: 1px solid #ffe6a9;
  color: #21170b;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.35), transparent 45%),
    linear-gradient(180deg, #f5cc76, #d99a33);
  box-shadow: 0 4px 0 #875719, 0 12px 36px rgba(216, 145, 45, 0.19), inset 0 1px 0 rgba(255, 255, 255, 0.6);
  transition: transform 0.12s, filter 0.15s, box-shadow 0.12s;
}
.deploy-btn::after {
  content: "";
  position: absolute;
  top: 0; bottom: 0; width: 35%;
  left: -50%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);
  transform: skewX(-18deg);
  animation: sheen 3.8s ease-in-out infinite;
}
.deploy-btn:hover { filter: brightness(1.06); transform: translateY(-1px); }
.deploy-btn:active { transform: translateY(3px); box-shadow: 0 1px 0 #875719, 0 6px 20px rgba(0, 0, 0, 0.3); }
.deploy-btn span {
  font-family: var(--font-head);
  font-size: clamp(15px, 1.7vw, 20px);
  font-weight: 900;
  letter-spacing: 0.14em;
  line-height: 1;
}
.deploy-btn small { font-size: 7px; font-weight: 800; letter-spacing: 0.17em; opacity: 0.6; }
.how-row {
  display: flex;
  gap: 14px;
  margin-top: 26px;
  max-width: 620px;
}
.how-item {
  display: flex;
  flex-direction: column;
  gap: 5px;
  flex: 1;
  padding-top: 8px;
  border-top: 1px solid rgba(241, 199, 111, 0.16);
}
.how-item b {
  font-family: var(--font-head);
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--gold);
}
.how-item span { font-size: 9px; line-height: 1.5; color: #8f826d; }
.start-foot {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 20px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: #766a58;
  text-transform: uppercase;
}
.sound-toggle {
  color: #a8967a;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.14em;
  border-bottom: 1px dotted rgba(168, 150, 122, 0.4);
  padding: 0 0 1px;
}
.sound-toggle:hover { color: var(--gold); }

/* end screen */
.end-screen { background: transparent; }
.end-screen .stars { z-index: 0; }
.end-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(7, 6, 5, 0.88);
  backdrop-filter: blur(3px);
}
.screen-shade {
  position: absolute; inset: 0;
  background: radial-gradient(60% 80% at 50% 45%, rgba(214, 143, 49, 0.16), transparent 65%);
}
.end-wrap {
  position: relative;
  z-index: 3;
  width: min(560px, 88vw);
  text-align: center;
  animation: rise 0.45s ease-out both;
}
.end-wrap .start-eyebrow { justify-content: center; }
.end-wrap h2 {
  font-family: var(--font-head);
  font-size: clamp(38px, 6vw, 72px);
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: 0.08em;
  margin: 0 0 10px;
  color: var(--gold-bright);
  text-shadow: 0 0 36px rgba(241, 199, 111, 0.2);
}
.end-wrap.defeat h2 { color: #ff8f7c; text-shadow: 0 0 36px rgba(255, 90, 70, 0.2); }
.end-wrap p { color: #b3a58d; font-size: 12px; margin: 0 auto 22px; max-width: 380px; line-height: 1.55; }
.end-stats {
  display: flex;
  justify-content: center;
  gap: 1px;
  margin: 0 auto 22px;
  border: 1px solid rgba(241, 199, 111, 0.18);
  border-radius: 9px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.025);
  width: min(420px, 100%);
}
.end-stats > div {
  flex: 1;
  padding: 10px 8px;
  border-right: 1px solid rgba(241, 199, 111, 0.12);
}
.end-stats > div:last-child { border-right: 0; }
.end-stats span { display: block; font-size: 6.5px; letter-spacing: 0.14em; font-weight: 800; color: var(--muted); margin-bottom: 3px; }
.end-stats b { font-family: var(--font-head); font-size: 24px; color: var(--gold-bright); font-variant-numeric: tabular-nums; }
.end-wrap .modal-actions { align-items: center; }
.end-wrap .deploy-btn { padding: 10px 26px; }
.end-wrap .start-foot { justify-content: center; margin-top: 18px; }

/* rotate screen */
.rotate-screen {
  display: none;
  z-index: 300;
  background:
    radial-gradient(60% 80% at 50% 40%, rgba(206, 135, 42, 0.15), transparent 65%),
    #0a0806;
  text-align: center;
}
.rotate-inner { padding: 24px; }
.phone-icon {
  width: 66px; height: 66px;
  margin: 0 auto 16px;
  color: var(--gold);
  animation: rotate-phone 2.8s ease-in-out infinite;
  transform-origin: 50% 50%;
}
.phone-icon svg { width: 100%; height: 100%; }
@keyframes rotate-phone {
  0%, 18% { transform: rotate(0deg); }
  45%, 100% { transform: rotate(90deg); }
}
.rotate-inner .eyebrow { font-size: 8px; letter-spacing: 0.3em; color: var(--gold); font-weight: 800; margin-bottom: 8px; }
.rotate-inner h2 {
  font-family: var(--font-head);
  font-size: 34px;
  line-height: 0.95;
  letter-spacing: 0.06em;
  margin: 0 0 12px;
  color: var(--gold-bright);
}
.rotate-inner p { color: var(--muted); font-size: 11px; line-height: 1.55; max-width: 260px; margin: 0 auto; }

/* ---------- responsive ---------- */
@media (max-width: 1100px) {
  :root { --shop-w: clamp(188px, 23vw, 236px); }
  .start-wrap { margin-right: 12vw; }
  .tower-card { min-height: 64px; }
  .tower-icon { width: 29px; height: 29px; }
  .tower-icon svg { width: 26px; height: 26px; }
  .tower-name { font-size: 8.5px; }
}

@media (max-height: 560px) {
  .shop-head { padding: 7px 9px 7px; }
  .brand-mark { width: 21px; height: 21px; }
  .brand-kicker { display: none; }
  .brand-name { font-size: 13px; letter-spacing: 0.13em; }
  .stats { margin-top: 6px; gap: 5px; }
  .stat { padding: 3px 6px; font-size: 13px; border-radius: 5px; }
  .stat svg { width: 13px; height: 13px; }
  .panel-title { padding: 6px 9px 5px; font-size: 7px; }
  .panel-title .panel-hint { font-size: 6px; }
  .tower-list { gap: 5px; padding: 0 7px 7px; }
  .tower-card { min-height: 54px; padding: 4px 3px 4px; border-radius: 7px; gap: 1px; }
  .tower-icon { width: 24px; height: 24px; }
  .tower-icon svg { width: 22px; height: 22px; }
  .tower-name { font-size: 7.5px; }
  .cost { font-size: 10px; }
  .cost svg { width: 8px; height: 8px; }
  .hotkey { font-size: 6px; top: 2px; left: 3px; }
  .shop-foot { padding: 5px 7px 8px; }
  .wave-status { font-size: 7.5px; padding-bottom: 4px; min-height: 15px; }
  .send-btn { padding: 7px 6px 6px; }
  .send-btn span { font-size: 13px; }
  .send-btn small { font-size: 6px; }
  .hud { padding: 7px 8px; }
  .hud-left { padding: 5px 8px 6px; min-width: 132px; border-radius: 7px; }
  .map-name { font-size: 6.5px; }
  #waveTag { font-size: 13px; }
  .wave-sub { font-size: 7px; }
  .icon-btn { width: 32px; height: 32px; border-radius: 7px; }
  .icon-btn svg { width: 16px; height: 16px; }
  .bossbar { top: 46px; }
  .toasts { bottom: 12px; }
  .toast { font-size: 10px; padding: 6px 10px; }

  .inspect-panel { padding: 8px; }
  .inspect-icon { width: 36px; height: 36px; }
  .inspect-icon svg { width: 28px; height: 28px; }
  #inspectName { font-size: 13px; }
  .inspect-desc { font-size: 8px; margin: 5px 1px 6px; line-height: 1.35; }
  .stat-grid { gap: 3px; margin-bottom: 5px; }
  .stat-grid > div { padding: 4px 5px; }
  .stat-grid b { font-size: 11px; }
  .target-btn { padding: 5px 6px; margin-bottom: 5px; }
  .upgrade-btn { padding: 6px 8px; }
  .up-label { font-size: 6px; }
  .up-cost { font-size: 13px; }
  .sell-btn { margin-top: 5px; padding: 5px; }

  .start-wrap { margin-right: 8vw; }
  .start-wrap h1 { font-size: clamp(36px, 6.8vw, 58px); }
  .start-tag { margin: 9px 0 13px; font-size: 10px; line-height: 1.45; }
  .start-eyebrow { margin-bottom: 7px; font-size: 6.5px; }
  .deploy-btn { padding: 9px 22px 8px; }
  .deploy-btn span { font-size: 15px; }
  .how-row { margin-top: 14px; gap: 10px; }
  .how-item { gap: 3px; padding-top: 5px; }
  .how-item span { font-size: 7.5px; }
  .start-foot { margin-top: 11px; }
  .end-wrap h2 { font-size: 40px; }
  .end-wrap p { font-size: 10px; margin-bottom: 14px; }
  .end-stats { margin-bottom: 14px; }
  .end-stats > div { padding: 7px 6px; }
  .end-stats b { font-size: 18px; }
}

@media (max-height: 420px) {
  .start-wrap { width: min(660px, 82vw); margin-right: 7vw; padding: 8px 0; }
  .start-wrap h1 { font-size: clamp(32px, 5.4vw, 48px); }
  .start-tag { margin: 7px 0 10px; font-size: 9px; max-width: 420px; }
  .start-tag br { display: none; }
  .deploy-btn { padding: 8px 20px 7px; }
  .deploy-btn span { font-size: 13px; }
  .how-row { margin-top: 11px; }
  .how-item span { font-size: 7px; line-height: 1.4; }
  .start-foot { margin-top: 8px; font-size: 7px; }
  .planet { bottom: -70vh; right: -14vw; }
}

@media (max-height: 360px) {
  .brand-kicker { display: none; }
  .brand-name { font-size: 11px; }
  .brand-mark { width: 19px; height: 19px; }
  .stats { margin-top: 4px; }
  .stat { font-size: 11px; padding: 2px 5px; }
  .panel-title { padding: 4px 7px 4px; }
  .tower-card { min-height: 48px; }
  .tower-icon { width: 21px; height: 21px; }
  .tower-icon svg { width: 19px; height: 19px; }
  .tower-name { font-size: 7px; }
  .cost { font-size: 9px; }
  .shop-foot { padding: 4px 6px 6px; }
  .wave-status { display: none; }
  .send-btn span { font-size: 12px; }
  .send-btn small { display: none; }
}

@media (min-width: 1500px) and (min-height: 800px) {
  :root { --shop-w: 288px; }
  .tower-card { min-height: 80px; }
  .tower-icon { width: 38px; height: 38px; }
  .tower-icon svg { width: 34px; height: 34px; }
  .tower-name { font-size: 10.5px; }
  .panel-title { font-size: 9px; }
}

/* portrait / tiny: request landscape */
@media (orientation: portrait) and (max-width: 1100px) {
  .rotate-screen { display: flex; }
  .app { filter: blur(2px) brightness(0.4); }
}
@media (max-width: 640px) and (orientation: portrait) {
  .start-screen, .end-screen { display: none; }
}

/* coarse pointers get a bit more spacing */
@media (pointer: coarse) {
  .tower-card:hover { transform: none; }
  .btn-primary, .btn-ghost, .close-btn, .icon-btn, .place-hint button { min-width: 34px; min-height: 34px; }
}

/* ============================================================
   Game data — towers, enemies, waves, map
   ============================================================ */

export const TOTAL_WAVES = 25;
export const START_CREDITS = 500;
export const START_LIVES = 20;

/* Map path control points in normalized map space (0..1). */
export const PATH_POINTS = [
  [-0.05, 0.64],
  [0.075, 0.64],
  [0.135, 0.35],
  [0.30, 0.265],
  [0.375, 0.585],
  [0.25, 0.80],
  [0.45, 0.885],
  [0.61, 0.725],
  [0.565, 0.36],
  [0.715, 0.19],
  [0.855, 0.335],
  [0.785, 0.645],
  [0.885, 0.775],
