/* Tiny procedural sound engine — no audio assets required. */

const clampGain = v => Math.max(0, Math.min(1, v));

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = localStorage.getItem('to-muted') === '1';
    this.last = {};
    this.ambience = null;
    this.noiseBuffer = null;
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return this.ctx;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.72;
      this.master.connect(this.ctx.destination);
      this.noiseBuffer = this.makeNoise();
      this.startAmbience();
    } catch { this.ctx = null; }
    return this.ctx;
  }

  makeNoise() {
    const len = this.ctx.sampleRate * 1.2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = 0.96 * last + 0.04 * white;
      data[i] = white * 0.7 + last * 0.6;
    }
    return buf;
  }

  startAmbience() {
    if (!this.ctx || this.ambience) return;
    try {
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuffer;
      src.loop = true;
      const lp = this.ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = 340;
      lp.Q.value = 0.4;
      const g = this.ctx.createGain();
      g.gain.value = 0.011;
      const lfo = this.ctx.createOscillator();
      const lfoGain = this.ctx.createGain();
      lfo.frequency.value = 0.07;
      lfoGain.gain.value = 0.005;
      lfo.connect(lfoGain).connect(g.gain);
      src.connect(lp).connect(g).connect(this.master);
      src.start();
      lfo.start();
      this.ambience = { src, g, lfo };
    } catch {}
  }

  setMuted(muted) {
    this.muted = muted;
    localStorage.setItem('to-muted', muted ? '1' : '0');
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.72, this.ctx.currentTime + 0.08);
    }
  }

  throttle(key, ms = 40) {
    const now = performance.now();
    if (this.last[key] && now - this.last[key] < ms) return false;
    this.last[key] = now;
    return true;
  }

  tone(opts) {
    if (!this.ctx || this.muted) return;
    const {
      freq = 440, endFreq = null, type = 'sine', dur = 0.12,
      gain = 0.06, delay = 0, attack = 0.006, filter = null, detune = 0,
    } = opts;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t0 + dur);
    osc.detune.value = detune;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(clampGain(gain), t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    let node = osc;
    if (filter) {
      const f = this.ctx.createBiquadFilter();
      f.type = filter.type || 'lowpass';
      f.frequency.value = filter.freq || 1200;
      f.Q.value = filter.q || 0.8;
      node.connect(f);
      node = f;
    }
    node.connect(g).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  noise(opts = {}) {
    if (!this.ctx || this.muted || !this.noiseBuffer) return;
    const { dur = 0.2, gain = 0.08, freq = 900, q = 0.8, type = 'lowpass', delay = 0 } = opts;
    const t0 = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t0);
    f.frequency.exponentialRampToValueAtTime(Math.max(80, freq * 0.32), t0 + dur);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  ui() {
    if (!this.ensure() || !this.throttle('ui', 30)) return;
    this.tone({ freq: 660, endFreq: 880, type: 'triangle', dur: 0.055, gain: 0.028 });
  }

  shot(kind) {
    if (!this.ensure() || !this.throttle('shot' + kind, 34)) return;
    if (kind === 'scout') {
      this.tone({ freq: 1130, endFreq: 280, type: 'square', dur: 0.085, gain: 0.038 });
      this.tone({ freq: 190, endFreq: 90, type: 'sine', dur: 0.06, gain: 0.02 });
    } else if (kind === 'ion') {
      this.tone({ freq: 260, endFreq: 940, type: 'sine', dur: 0.24, gain: 0.05 });
      this.tone({ freq: 520, endFreq: 1500, type: 'triangle', dur: 0.18, gain: 0.025, delay: 0.02 });
    } else if (kind === 'rocket') {
      this.noise({ dur: 0.36, gain: 0.075, freq: 800, q: 0.7 });
      this.tone({ freq: 120, endFreq: 45, type: 'sawtooth', dur: 0.26, gain: 0.035 });
    } else if (kind === 'laser') {
      this.tone({ freq: 1450, endFreq: 220, type: 'sawtooth', dur: 0.13, gain: 0.038, filter: { type: 'lowpass', freq: 2600 } });
    } else if (kind === 'sniper') {
      this.noise({ dur: 0.16, gain: 0.1, freq: 2400, q: 1.6, type: 'bandpass' });
      this.tone({ freq: 150, endFreq: 42, type: 'sine', dur: 0.28, gain: 0.09 });
    } else if (kind === 'jedi') {
      this.tone({ freq: 160, endFreq: 120, type: 'sawtooth', dur: 0.28, gain: 0.028, filter: { type: 'lowpass', freq: 600 } });
      this.tone({ freq: 740, endFreq: 480, type: 'sine', dur: 0.16, gain: 0.026 });
    }
  }

  explosion(big = false) {
    if (!this.ensure() || !this.throttle('boom', big ? 60 : 24)) return;
    this.noise({ dur: big ? 0.6 : 0.26, gain: big ? 0.12 : 0.06, freq: big ? 700 : 1100, q: 0.5 });
    this.tone({ freq: big ? 95 : 140, endFreq: 32, type: 'sine', dur: big ? 0.55 : 0.24, gain: big ? 0.09 : 0.04 });
  }

  place() {
    if (!this.ensure()) return;
    [330, 495, 660].forEach((f, i) => this.tone({ freq: f, endFreq: f * 1.02, type: 'triangle', dur: 0.11, gain: 0.035, delay: i * 0.055 }));
    this.noise({ dur: 0.14, gain: 0.03, freq: 600 });
  }

  error() {
    if (!this.ensure()) return;
    this.tone({ freq: 150, endFreq: 110, type: 'square', dur: 0.13, gain: 0.045 });
    this.tone({ freq: 120, endFreq: 85, type: 'square', dur: 0.13, gain: 0.03, delay: 0.09 });
  }

  upgrade() {
    if (!this.ensure()) return;
    [392, 523, 659, 784].forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.18, gain: 0.035, delay: i * 0.06 }));
  }

  sell() {
    if (!this.ensure()) return;
    [740, 620, 460].forEach((f, i) => this.tone({ freq: f, endFreq: f * 0.7, type: 'triangle', dur: 0.12, gain: 0.03, delay: i * 0.05 }));
  }

  waveStart() {
    if (!this.ensure()) return;
    this.tone({ freq: 98, endFreq: 196, type: 'sawtooth', dur: 0.7, gain: 0.05, filter: { type: 'lowpass', freq: 900 } });
    this.tone({ freq: 392, endFreq: 587, type: 'triangle', dur: 0.5, gain: 0.04, delay: 0.12 });
    this.noise({ dur: 0.7, gain: 0.025, freq: 400 });
  }

  waveClear() {
    if (!this.ensure()) return;
    [523, 659, 784, 1046].forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.3, gain: 0.035, delay: i * 0.08 }));
  }

  leak() {
    if (!this.ensure()) return;
    this.tone({ freq: 220, endFreq: 55, type: 'sawtooth', dur: 0.5, gain: 0.08, filter: { type: 'lowpass', freq: 800 } });
    this.noise({ dur: 0.3, gain: 0.07, freq: 300 });
  }

  bossWarn() {
    if (!this.ensure()) return;
    this.tone({ freq: 64, endFreq: 64, type: 'sawtooth', dur: 1.2, gain: 0.06, filter: { type: 'lowpass', freq: 240 } });
    this.tone({ freq: 68, endFreq: 68, type: 'sawtooth', dur: 1.2, gain: 0.05, delay: 0.18, detune: -14 });
    this.noise({ dur: 1.1, gain: 0.035, freq: 180, delay: 0.1 });
  }

  kill(big = false) {
    if (!this.ensure() || !this.throttle('kill', 55)) return;
    this.noise({ dur: big ? 0.32 : 0.13, gain: big ? 0.08 : 0.032, freq: big ? 900 : 1600, type: 'bandpass', q: 1.1 });
    if (big) this.explosion(true);
  }

  victory() {
    if (!this.ensure()) return;
    const notes = [523, 659, 784, 1046, 1318, 1568];
    notes.forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.5, gain: 0.04, delay: i * 0.12 }));
    [261, 392, 523].forEach((f, i) => this.tone({ freq: f, type: 'sine', dur: 1.4, gain: 0.05, delay: i * 0.05 }));
  }

  defeat() {
    if (!this.ensure()) return;
    [392, 349, 311, 262, 196].forEach((f, i) => this.tone({ freq: f, endFreq: f * 0.94, type: 'triangle', dur: 0.5, gain: 0.045, delay: i * 0.16 }));
    this.noise({ dur: 1.4, gain: 0.05, freq: 300 });
  }
}

/* ============================================================
   Canvas art — procedural Tatooine outpost
   All game visuals are drawn with the 2D canvas (no assets).
   ============================================================ */

import { DECOR, ENEMY_TYPES, TOWERS, clamp } from './data.js';

const TAU = Math.PI * 2;

export function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

function tracePoints(ctx, pts) {
  if (!pts.length) return;
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
}

function offsetPath(pts, off) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    const prev = pts[Math.max(0, i - 1)];
    const next = pts[Math.min(pts.length - 1, i + 1)];
    let dx = next[0] - prev[0];
    let dy = next[1] - prev[1];
    const l = Math.hypot(dx, dy) || 1;
    dx /= l; dy /= l;
    out.push([p[0] - dy * off, p[1] + dx * off]);
  }
  return out;
}

/* ============================================================
   STATIC MAP
   ============================================================ */

export function buildBackground(w, h, pathPts, S, dpr = 1) {
  const c = document.createElement('canvas');
  c.width = Math.max(1, Math.floor(w * dpr));
  c.height = Math.max(1, Math.floor(h * dpr));
  const ctx = c.getContext('2d');
  ctx.scale(dpr, dpr);
  const rng = mulberry32(0x5a7b21);
  const m = Math.min(w, h);

  // --- base sand -------------------------------------------------
  const bg = ctx.createLinearGradient(0, 0, w * 0.4, h);
  bg.addColorStop(0, '#d8ad72');
  bg.addColorStop(0.44, '#cfa067');
  bg.addColorStop(1, '#bf8e58');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);

  // huge soft dune bands
  const dunes = [
    { x: -0.05, y: 0.02, w: 0.52, h: 0.28, c: 'rgba(246, 215, 163, 0.24)' },
    { x: 0.45, y: 0.02, w: 0.62, h: 0.22, c: 'rgba(246, 215, 163, 0.17)' },
    { x: 0.03, y: 0.78, w: 0.42, h: 0.30, c: 'rgba(160, 112, 64, 0.15)' },
    { x: 0.55, y: 0.73, w: 0.50, h: 0.34, c: 'rgba(247, 213, 157, 0.14)' },
    { x: 0.33, y: 0.35, w: 0.37, h: 0.23, c: 'rgba(246, 215, 163, 0.10)' },
  ];
  for (const d of dunes) {
    ctx.save();
    ctx.translate(d.x * w, d.y * h);
    ctx.beginPath();
    ctx.ellipse(d.w * w * 0.5, d.h * h * 0.55, d.w * w * 0.5, d.h * h * 0.5, -0.16, 0, TAU);
    const g = ctx.createLinearGradient(0, 0, 0, d.h * h);
    g.addColorStop(0, d.c);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fill();
    ctx.restore();
  }

  // wind ripples
  ctx.save();
  ctx.lineCap = 'round';
  for (let i = 0; i < 44; i++) {
    const x = rng() * w;
    const y = rng() * h;
    if (distanceToPath(x, y, pathPts) < 44 * S) continue;
    const len = (12 + rng() * 46) * S;
    const bend = (rng() - 0.5) * 18 * S;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x + len * 0.5, y + bend, x + len, y + bend * 0.2);
    ctx.strokeStyle = `rgba(126, 85, 45, ${0.05 + rng() * 0.06})`;
    ctx.lineWidth = (0.8 + rng() * 1.4) * S;
    ctx.stroke();
  }
  ctx.restore();

  // speckles / pebbles
  for (let i = 0; i < 380; i++) {
    const x = rng() * w;
    const y = rng() * h;
    const s = (0.4 + rng() * 1.7) * S;
    ctx.fillStyle = rng() > 0.5 ? `rgba(111, 74, 38, ${0.05 + rng() * 0.15})` : `rgba(250, 226, 174, ${0.06 + rng() * 0.16})`;
    ctx.beginPath();
    ctx.arc(x, y, s, 0, TAU);
    ctx.fill();
  }

  // --- race-track path -------------------------------------------
  const pw = clamp(33 * S, 23, 52);
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // path ambient shadow
  tracePoints(ctx, offsetPath(pathPts, 5 * S));
  ctx.strokeStyle = 'rgba(79, 48, 23, 0.20)';
  ctx.lineWidth = pw + 17 * S;
  ctx.stroke();

  // dark outer bank
  tracePoints(ctx, pathPts);
  ctx.strokeStyle = '#9c6a3b';
  ctx.lineWidth = pw + 9 * S;
  ctx.stroke();

  // packed sand
  tracePoints(ctx, pathPts);
  const pathGrad = ctx.createLinearGradient(0, 0, w, h);
  pathGrad.addColorStop(0, '#e8c48c');
  pathGrad.addColorStop(0.5, '#edcc95');
  pathGrad.addColorStop(1, '#e3bb80');
  ctx.strokeStyle = pathGrad;
  ctx.lineWidth = pw;
  ctx.stroke();

  // inner highlight
  tracePoints(ctx, offsetPath(pathPts, -pw * 0.12));
  ctx.strokeStyle = 'rgba(255, 233, 184, 0.22)';
  ctx.lineWidth = pw * 0.5;
  ctx.stroke();

  // wheel tracks
  ctx.setLineDash([12 * S, 20 * S]);
  ctx.lineCap = 'butt';
  for (const off of [-pw * 0.19, pw * 0.19]) {
    tracePoints(ctx, offsetPath(pathPts, off));
    ctx.strokeStyle = 'rgba(129, 84, 41, 0.17)';
    ctx.lineWidth = 1.8 * S;
    ctx.stroke();
  }
  ctx.setLineDash([]);
  ctx.restore();

  // stones lining the path
  for (let i = 0; i < pathPts.length; i += 3) {
    const p = pathPts[i];
    const prev = pathPts[Math.max(0, i - 1)];
    const next = pathPts[Math.min(pathPts.length - 1, i + 1)];
    let dx = next[0] - prev[0];
    let dy = next[1] - prev[1];
    const l = Math.hypot(dx, dy) || 1;
    dx /= l; dy /= l;
    for (const side of [-1, 1]) {
      if (rng() > 0.82) continue;
      const off = (pw / 2 + 3 + rng() * 7) * side;
      const sx = p[0] - dy * off;
      const sy = p[1] + dx * off;
      drawPebble(ctx, sx, sy, (1.5 + rng() * 3) * S, rng, rng() * TAU);
    }
  }

  // path edge scrub
  for (let i = 0; i < 34; i++) {
    const p = pathPts[Math.floor(rng() * pathPts.length)];
    if (!p) continue;
    const ang = rng() * TAU;
    const off = pw * 0.5 + (4 + rng() * 14) * S;
    const x = p[0] + Math.cos(ang) * off;
    const y = p[1] + Math.sin(ang) * off;
    ctx.strokeStyle = `rgba(105, 108, 54, ${0.14 + rng() * 0.12})`;
    ctx.lineWidth = 1.1 * S;
    ctx.beginPath();
    for (let b = -1; b <= 1; b++) {
      ctx.moveTo(x + b * 2 * S, y + 3 * S);
      ctx.quadraticCurveTo(x + b * 3 * S, y - 4 * S, x + b * 6 * S, y - 6 * S);
    }
    ctx.stroke();
  }

  // --- spawn marker ----------------------------------------------
  const first = pathPts[0];
  ctx.save();
  ctx.translate(first[0] + 10 * S, first[1]);
  ctx.globalAlpha = 0.5;
  ctx.fillStyle = '#2a1d11';
  for (let i = 0; i < 3; i++) {
    ctx.save();
    ctx.translate(0, (i - 1) * 11 * S);
    ctx.rotate(Math.PI / 4);
    ctx.fillRect(-5 * S, -5 * S, 10 * S, 10 * S);
    ctx.fillStyle = '#d8a347';
    ctx.fillRect(-2 * S, -2 * S, 4 * S, 4 * S);
    ctx.fillStyle = '#2a1d11';
    ctx.restore();
  }
  ctx.restore();

  // --- decorations ----------------------------------------------
  for (const d of DECOR) {
    const x = d.x * w;
    const y = d.y * h;
    const r = d.r * m;
    drawDecor(ctx, d, x, y, r, S, rng);
  }

  // --- relay base -------------------------------------------------
  drawRelayBaseStatic(ctx, w * 0.952, h * 0.60, m, S, rng);

  // vignette
  const vg = ctx.createRadialGradient(w * 0.5, h * 0.5, Math.min(w, h) * 0.28, w * 0.5, h * 0.5, Math.max(w, h) * 0.82);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(46, 26, 9, 0.30)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, w, h);

  return c;
}

function distanceToPath(x, y, pts) {
  let best = Infinity;
  for (let i = 0; i < pts.length - 1; i++) {
    const ax = pts[i][0], ay = pts[i][1], bx = pts[i + 1][0], by = pts[i + 1][1];
    const dx = bx - ax, dy = by - ay;
    const l2 = dx * dx + dy * dy || 1;
    let t = ((x - ax) * dx + (y - ay) * dy) / l2;
    t = clamp(t, 0, 1);
    const px = ax + dx * t, py = ay + dy * t;
    best = Math.min(best, Math.hypot(x - px, y - py));
  }
  return best;
}

function drawPebble(ctx, x, y, r, rng, rot) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.fillStyle = 'rgba(86, 57, 32, 0.26)';
  ctx.beginPath();
  ctx.ellipse(0, r * 0.3, r * 1.1, r * 0.7, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = rng() > 0.5 ? '#aa7a4b' : '#8c613a';
  ctx.beginPath();
  ctx.ellipse(0, 0, r, r * 0.72, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(247, 216, 165, 0.32)';
  ctx.beginPath();
  ctx.ellipse(-r * 0.22, -r * 0.22, r * 0.48, r * 0.28, -0.3, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawRock(ctx, x, y, r, rng) {
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = 'rgba(53, 31, 13, 0.30)';
  ctx.beginPath();
  ctx.ellipse(r * 0.3, r * 0.55, r * 1.15, r * 0.56, -0.15, 0, TAU);
  ctx.fill();

  const pts = [];
  const n = 7;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU;
    const rr = r * (0.68 + rng() * 0.35);
    pts.push([Math.cos(a) * rr, Math.sin(a) * rr * 0.76 - r * 0.12]);
  }
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < n; i++) ctx.lineTo(pts[i][0], pts[i][1]);
  ctx.closePath();
  const g = ctx.createLinearGradient(-r, -r, r, r);
  g.addColorStop(0, '#a67c51');
  g.addColorStop(0.55, '#7a5738');
  g.addColorStop(1, '#5e422b');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = 'rgba(57, 38, 21, 0.42)';
  ctx.lineWidth = r * 0.09;
  ctx.stroke();

  // lit face
  ctx.beginPath();
  ctx.moveTo(-r * 0.7, -r * 0.15);
  ctx.lineTo(-r * 0.1, -r * 0.72);
  ctx.lineTo(r * 0.42, -r * 0.28);
  ctx.lineTo(-r * 0.05, -r * 0.02);
  ctx.closePath();
  ctx.fillStyle = 'rgba(232, 193, 137, 0.26)';
  ctx.fill();
  ctx.restore();
}

function drawVaporator(ctx, x, y, r, S) {
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = 'rgba(55, 33, 15, 0.3)';
  ctx.beginPath();
  ctx.ellipse(r * 0.6, r * 0.35, r * 2.1, r * 0.55, 0.1, 0, TAU);
  ctx.fill();

  const hgt = r * 6.1;
  const wdt = Math.max(2.2 * S, r * 0.6);
  const g = ctx.createLinearGradient(-wdt, 0, wdt, 0);
  g.addColorStop(0, '#6f6d64');
  g.addColorStop(0.45, '#c0bbab');
  g.addColorStop(0.7, '#9a968a');
  g.addColorStop(1, '#5a5851');
  ctx.fillStyle = g;
  ctx.fillRect(-wdt, -hgt, wdt * 2, hgt);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.16)';
  ctx.fillRect(-wdt * 0.45, -hgt + 2, wdt * 0.4, hgt - 4);

  // rings
  for (let i = 1; i < 5; i++) {
    ctx.fillStyle = 'rgba(61, 58, 51, 0.4)';
    ctx.fillRect(-wdt * 1.15, -hgt * (i / 5), wdt * 2.3, Math.max(1, r * 0.18));
  }
  // head
  ctx.fillStyle = '#8f8c80';
  ctx.beginPath();
  ctx.ellipse(0, -hgt, r * 1.1, r * 0.55, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#5b594f';
  ctx.beginPath();
  ctx.ellipse(0, -hgt - r * 0.28, r * 0.7, r * 0.3, 0, 0, TAU);
  ctx.fill();
  // little solar panel
  ctx.save();
  ctx.translate(r * 1.35, -hgt * 0.74);
  ctx.rotate(-0.25);
  ctx.fillStyle = '#26333a';
  ctx.fillRect(-r * 0.9, -r * 0.45, r * 1.8, r * 0.9);
  ctx.strokeStyle = 'rgba(112, 172, 186, 0.45)';
  ctx.lineWidth = 0.6 * S;
  ctx.strokeRect(-r * 0.9, -r * 0.45, r * 1.8, r * 0.9);
  ctx.restore();
  ctx.restore();
}

function drawHut(ctx, x, y, r, S, rng) {
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = 'rgba(51, 30, 13, 0.32)';
  ctx.beginPath();
  ctx.ellipse(r * 0.55, r * 0.65, r * 1.5, r * 0.62, -0.1, 0, TAU);
  ctx.fill();

  // dome
  const g = ctx.createRadialGradient(-r * 0.4, -r * 0.5, r * 0.1, 0, 0, r * 1.25);
  g.addColorStop(0, '#e6cfa4');
  g.addColorStop(0.5, '#c8aa7b');
  g.addColorStop(1, '#9c7c52');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, r, Math.PI, TAU);
  ctx.quadraticCurveTo(r, r * 0.35, r * 0.8, r * 0.45);
  ctx.lineTo(-r * 0.8, r * 0.45);
  ctx.quadraticCurveTo(-r, r * 0.35, -r, 0);
  ctx.closePath();
  ctx.fill();

  // door
  ctx.fillStyle = '#3a2a1b';
  roundRect(ctx, -r * 0.26, -r * 0.42, r * 0.52, r * 0.85, r * 0.26);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 197, 100, 0.3)';
  ctx.fillRect(-r * 0.2, -r * 0.32, r * 0.4, r * 0.06);

  // antenna
  ctx.strokeStyle = '#6b5a44';
  ctx.lineWidth = Math.max(0.8 * S, r * 0.055);
  ctx.beginPath();
  ctx.moveTo(r * 0.46, -r * 0.62);
  ctx.lineTo(r * 0.72, -r * 1.4);
  ctx.stroke();
  ctx.fillStyle = '#d6b379';
  ctx.beginPath();
  ctx.arc(r * 0.72, -r * 1.4, r * 0.11, 0, TAU);
  ctx.fill();

  // seam
  ctx.strokeStyle = 'rgba(100, 72, 42, 0.4)';
  ctx.lineWidth = 0.7 * S;
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.82, Math.PI * 1.06, Math.PI * 1.94);
  ctx.stroke();
  ctx.restore();
}

function drawBone(ctx, x, y, r, S, rng) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(-0.35 + rng() * 0.7);
  ctx.fillStyle = 'rgba(54, 32, 14, 0.25)';
  ctx.beginPath();
  ctx.ellipse(r * 0.4, r * 0.32, r * 1.7, r * 0.38, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#d3bd98';
  ctx.lineWidth = Math.max(1.1 * S, r * 0.14);
  ctx.lineCap = 'round';
  // spine
  ctx.beginPath();
  ctx.moveTo(-r * 1.6, 0);
  ctx.quadraticCurveTo(0, r * 0.3, r * 1.7, -r * 0.05);
  ctx.stroke();
  // ribs
  for (let i = 0; i < 5; i++) {
    const t = i / 4;
    const rx = -r * 1.1 + t * r * 2;
    const ry = Math.sin(t * Math.PI) * r * 0.2;
    ctx.beginPath();
    ctx.moveTo(rx, ry);
    ctx.quadraticCurveTo(rx + r * 0.2, -r * 0.7, rx + r * 0.65, -r * 0.85);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(rx, ry);
    ctx.quadraticCurveTo(rx + r * 0.05, r * 0.4, rx + r * 0.35, r * 0.6);
    ctx.stroke();
  }
  // skull
  ctx.fillStyle = '#d8c39f';
  ctx.beginPath();
  ctx.ellipse(r * 1.48, -r * 0.15, r * 0.42, r * 0.3, 0.2, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#5a452d';
  ctx.beginPath();
  ctx.arc(r * 1.35, -r * 0.22, r * 0.08, 0, TAU);
  ctx.arc(r * 1.58, -r * 0.24, r * 0.08, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawCactus(ctx, x, y, r, S) {
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = 'rgba(53, 33, 15, 0.25)';
  ctx.beginPath();
  ctx.ellipse(r * 0.4, r * 0.15, r * 0.8, r * 0.28, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#7b7c46';
  ctx.lineWidth = Math.max(1.2 * S, r * 0.38);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(0, r * 0.1);
  ctx.lineTo(0, -r * 1.35);
  ctx.moveTo(0, -r * 0.4);
  ctx.quadraticCurveTo(-r * 0.65, -r * 0.55, -r * 0.65, -r * 0.95);
  ctx.moveTo(0, -r * 0.75);
  ctx.quadraticCurveTo(r * 0.55, -r * 0.9, r * 0.55, -r * 1.25);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(170, 180, 104, 0.5)';
  ctx.lineWidth = Math.max(0.5 * S, r * 0.1);
  ctx.beginPath();
  ctx.moveTo(-r * 0.12, r * 0.05);
  ctx.lineTo(-r * 0.12, -r * 1.3);
  ctx.stroke();
  ctx.restore();
}

function drawCrate(ctx, x, y, r, S) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(-0.1);
  ctx.fillStyle = 'rgba(50, 30, 12, 0.28)';
  ctx.fillRect(-r * 0.8 + 2, -r * 0.6 + 3, r * 1.7, r * 1.3);
  ctx.fillStyle = '#7e6441';
  ctx.fillRect(-r * 0.85, -r * 0.65, r * 1.7, r * 1.3);
  ctx.strokeStyle = '#57432b';
  ctx.lineWidth = 1.2 * S;
  ctx.strokeRect(-r * 0.85, -r * 0.65, r * 1.7, r * 1.3);
  ctx.beginPath();
  ctx.moveTo(-r * 0.85, -r * 0.65);
  ctx.lineTo(r * 0.85, r * 0.65);
  ctx.moveTo(r * 0.85, -r * 0.65);
  ctx.lineTo(-r * 0.85, r * 0.65);
  ctx.strokeStyle = 'rgba(208, 169, 102, 0.35)';
  ctx.stroke();
  ctx.restore();
}

function drawDecor(ctx, d, x, y, r, S, rng) {
  switch (d.type) {
    case 'rock': drawRock(ctx, x, y, r, rng); break;
    case 'vaporator': drawVaporator(ctx, x, y, r, S); break;
    case 'hut': drawHut(ctx, x, y, r, S, rng); break;
    case 'bone': drawBone(ctx, x, y, r, S, rng); break;
    case 'cactus': drawCactus(ctx, x, y, r, S); break;
    case 'crate': drawCrate(ctx, x, y, r, S); break;
    default: break;
  }
}

function drawRelayBaseStatic(ctx, x, y, m, S, rng) {
  const R = clamp(m * 0.055, 22, 54);
  ctx.save();
  ctx.translate(x, y);

  // landing pad
  ctx.fillStyle = 'rgba(49, 30, 13, 0.32)';
  ctx.beginPath();
  ctx.ellipse(0, R * 0.34, R * 1.4, R * 0.72, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#9b9790';
  ctx.beginPath();
  ctx.ellipse(0, 0, R * 1.25, R * 0.75, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#6e6a63';
  ctx.lineWidth = Math.max(1.4 * S, R * 0.05);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(233, 205, 151, 0.35)';
  ctx.lineWidth = Math.max(1 * S, R * 0.035);
  ctx.beginPath();
  ctx.ellipse(0, 0, R * 0.88, R * 0.52, 0, 0, TAU);
  ctx.stroke();
  // pad stripes
  ctx.strokeStyle = 'rgba(45, 38, 28, 0.35)';
  ctx.lineWidth = Math.max(1 * S, R * 0.06);
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(-R * 0.5 + i * R * 0.35, R * 0.42);
    ctx.lineTo(-R * 0.4 + i * R * 0.35, R * 0.6);
    ctx.stroke();
  }

  // dome
  const dh = R * 0.98;
  const g = ctx.createLinearGradient(0, -dh, 0, 0);
  g.addColorStop(0, '#c9c3b8');
  g.addColorStop(0.48, '#8f8b82');
  g.addColorStop(1, '#5d5a53');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, -R * 0.12, dh, Math.PI, TAU);
  ctx.lineTo(dh, -R * 0.12);
  ctx.lineTo(-dh, -R * 0.12);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#4e4a42';
  ctx.lineWidth = Math.max(1.2 * S, R * 0.05);
  ctx.stroke();

  // blue reactor window
  ctx.fillStyle = '#264a5c';
  roundRect(ctx, -R * 0.34, -R * 0.72, R * 0.68, R * 0.3, R * 0.15);
  ctx.fill();
  ctx.fillStyle = 'rgba(104, 225, 255, 0.85)';
  roundRect(ctx, -R * 0.27, -R * 0.67, R * 0.54, R * 0.19, R * 0.1);
  ctx.fill();

  // tower / antenna
  ctx.strokeStyle = '#605c54';
  ctx.lineWidth = Math.max(1.4 * S, R * 0.06);
  ctx.beginPath();
  ctx.moveTo(R * 0.52, -R * 0.35);
  ctx.lineTo(R * 0.72, -R * 1.3);
  ctx.stroke();
  ctx.fillStyle = '#e6b75f';
  ctx.beginPath();
  ctx.arc(R * 0.72, -R * 1.32, Math.max(1.4 * S, R * 0.1), 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255, 223, 146, 0.35)';
  ctx.lineWidth = 0.8 * S;
  ctx.beginPath();
  ctx.arc(R * 0.72, -R * 1.32, R * 0.2, 0, TAU);
  ctx.stroke();

  // side fins
  ctx.fillStyle = '#706b61';
  ctx.beginPath();
  ctx.moveTo(-dh * 0.9, -R * 0.14);
  ctx.lineTo(-dh * 1.25, R * 0.22);
  ctx.lineTo(-dh * 0.7, R * 0.15);
  ctx.closePath();
  ctx.fill();

  // beacon lights
  for (let i = 0; i < 3; i++) {
    const a = -0.6 + i * 0.6;
    ctx.fillStyle = i === 1 ? 'rgba(255, 208, 105, 0.9)' : 'rgba(255, 130, 95, 0.8)';
    ctx.beginPath();
    ctx.arc(Math.cos(a) * R * 1.02, Math.sin(a) * R * 0.56 + R * 0.1, Math.max(0.8 * S, R * 0.04), 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

/* ============================================================
   DYNAMIC MAP PIECES
   ============================================================ */

export function drawBaseShield(ctx, w, h, time, flash) {
  const m = Math.min(w, h);
  const R = clamp(m * 0.055, 22, 54);
  const x = w * 0.952;
  const y = h * 0.60 - R * 0.12;
  const pulse = 0.06 + Math.sin(time * 1.7) * 0.015 + flash * 0.22;
  ctx.save();
  ctx.translate(x, y);
  const rad = R * 1.55;
  const g = ctx.createRadialGradient(0, -R * 0.2, rad * 0.25, 0, -R * 0.2, rad);
  g.addColorStop(0, `rgba(112, 225, 255, ${0.035 + flash * 0.1})`);
  g.addColorStop(0.7, `rgba(80, 190, 230, ${0.06 + pulse * 0.15})`);
  g.addColorStop(1, 'rgba(80, 190, 230, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, -R * 0.2, rad, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = `rgba(122, 226, 255, ${0.22 + pulse + flash * 0.4})`;
  ctx.lineWidth = 1.2;
  ctx.setLineDash([3, 5]);
  ctx.lineDashOffset = -time * 12;
  ctx.beginPath();
  ctx.arc(0, -R * 0.2, rad * 0.82, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);
  // beacon blink
  const blink = (Math.sin(time * 3.2) + 1) * 0.5;
  ctx.fillStyle = `rgba(255, 205, 100, ${0.3 + blink * 0.7})`;
  ctx.shadowColor = 'rgba(255, 200, 90, 0.8)';
  ctx.shadowBlur = 8;
  ctx.beginPath();
  ctx.arc(R * 0.72, -R * 1.32, 1.6, 0, TAU);
  ctx.fill();
  ctx.restore();
}

/* ============================================================
   TOWERS
   ============================================================ */

export function drawRange(ctx, x, y, r, color = '#f1c76f', alpha = 1) {
  ctx.save();
  ctx.globalAlpha = alpha;
  const g = ctx.createRadialGradient(x, y, r * 0.15, x, y, r);
  g.addColorStop(0, 'rgba(255,255,255,0.015)');
  g.addColorStop(0.75, color + '12');
  g.addColorStop(1, color + '24');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = color + 'aa';
  ctx.lineWidth = 1.2;
  ctx.setLineDash([5, 6]);
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.restore();
}

export function drawTowerShadow(ctx, tower, S) {
  ctx.save();
  ctx.translate(tower.x, tower.y);
  ctx.fillStyle = 'rgba(47, 29, 12, 0.30)';
  ctx.beginPath();
  ctx.ellipse(3 * S, 6 * S, 22 * S, 11 * S, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawTower(ctx, tower, time, S, selected = false, alpha = 1) {
  const def = TOWERS[tower.type];
  if (!def) return;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(tower.x, tower.y);
  ctx.scale(S, S);
  const ang = tower.angle || 0;
  const lvl = tower.level || 1;
  const accent = def.color;

  // base pad
  ctx.fillStyle = 'rgba(42, 27, 13, 0.22)';
  ctx.beginPath();
  ctx.ellipse(2, 5, 19.5, 10.5, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#39362f';
  ctx.beginPath();
  ctx.arc(0, 0, 17, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#5f5a50';
  ctx.lineWidth = 1.4;
  ctx.stroke();
  // pad rim
  const rim = ctx.createLinearGradient(0, -17, 0, 17);
  rim.addColorStop(0, '#8d8679');
  rim.addColorStop(0.5, '#6b655b');
  rim.addColorStop(1, '#45413a');
  ctx.strokeStyle = rim;
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.arc(0, 0, 15.4, 0, TAU);
  ctx.stroke();
  ctx.fillStyle = '#2c2a25';
  ctx.beginPath();
  ctx.arc(0, 0, 13.6, 0, TAU);
  ctx.fill();
  // level pips
  for (let i = 0; i < 4; i++) {
    const a = -Math.PI / 2 + (i - 1.5) * 0.38;
    ctx.fillStyle = i < lvl ? accent : 'rgba(255,255,255,0.10)';
    ctx.beginPath();
    ctx.arc(Math.cos(a) * 16.5, Math.sin(a) * 16.5, 1.35, 0, TAU);
    ctx.fill();
  }

  if (tower.type === 'scout') {
    drawScout(ctx, ang, tower, lvl, accent, time);
  } else if (tower.type === 'ion') {
    drawIon(ctx, ang, tower, lvl, accent, time);
  } else if (tower.type === 'rocket') {
    drawRocketPod(ctx, ang, tower, lvl, accent);
  } else if (tower.type === 'laser') {
    drawLaser(ctx, ang, tower, lvl, accent, time);
  } else if (tower.type === 'jedi') {
    drawJedi(ctx, ang, tower, lvl, accent, time);
  } else if (tower.type === 'bounty') {
    drawBounty(ctx, ang, tower, lvl, accent, time);
  }

  if (selected) {
    ctx.strokeStyle = 'rgba(255, 225, 160, 0.95)';
    ctx.lineWidth = 1.4;
    ctx.setLineDash([4, 5]);
    ctx.lineDashOffset = -time * 22;
    ctx.beginPath();
    ctx.arc(0, 0, 21.5, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    // brackets
    ctx.strokeStyle = '#ffe9b0';
    ctx.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      const a = i * Math.PI / 2 + time * 0.45;
      const r1 = 24.5;
      ctx.beginPath();
      ctx.arc(0, 0, r1, a - 0.1, a + 0.1);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function drawScout(ctx, ang, tower, lvl, accent, time) {
  const recoil = tower.recoil || 0;
  // body
  ctx.fillStyle = '#4a5058';
  ctx.beginPath();
  ctx.arc(0, -1, 9.3, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#7b838d';
  ctx.lineWidth = 1;
  ctx.stroke();
  // twin barrels
  ctx.save();
  ctx.rotate(ang);
  const back = -recoil * 2.4;
  for (const side of [-1.9, 1.9]) {
    ctx.fillStyle = '#9aa4af';
    roundRect(ctx, 5 + back, side - 1.15, 15, 2.3, 1.1);
    ctx.fill();
    ctx.fillStyle = '#3a3f46';
    ctx.fillRect(17.5 + back, side - 1.25, 2.2, 2.5);
  }
  // housing
  ctx.fillStyle = '#33383f';
  roundRect(ctx, 2 + back, -4.2, 8, 8.4, 2.4);
  ctx.fill();
  ctx.fillStyle = accent;
  ctx.beginPath();
  ctx.arc(4.5 + back, 0, 2.4, 0, TAU);
  ctx.fill();
  if (lvl >= 3) {
    ctx.fillStyle = '#c7d2de';
    roundRect(ctx, 9 + back, -5.6, 12, 1.7, 0.85);
    ctx.fill();
    roundRect(ctx, 9 + back, 3.9, 12, 1.7, 0.85);
    ctx.fill();
  }
  ctx.restore();
  // helmet on top
  ctx.fillStyle = '#e8e4d8';
  ctx.beginPath();
  ctx.arc(-2.5, -6.5, 3.5, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#25282c';
  ctx.beginPath();
  ctx.arc(-1.4, -6.8, 2.4, -0.5, 1.4);
  ctx.fill();
  // antenna
  ctx.strokeStyle = '#aeb6bf';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(-4, -9.6);
  ctx.lineTo(-6, -13.2);
  ctx.stroke();
  ctx.fillStyle = accent;
  ctx.beginPath();
  ctx.arc(-6, -13.2, 1.1, 0, TAU);
  ctx.fill();
}

function drawIon(ctx, ang, tower, lvl, accent, time) {
  // struts
  ctx.strokeStyle = '#5c6d76';
  ctx.lineWidth = 1.6;
  for (let i = 0; i < 3; i++) {
    const a = i * (TAU / 3) + 0.5;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * 6, Math.sin(a) * 6);
    ctx.lineTo(Math.cos(a) * 11, Math.sin(a) * 11);
    ctx.stroke();
  }
  // glowing core
  const pulse = 0.75 + Math.sin(time * 3 + (tower.phase || 0)) * 0.18;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(0, -1, 0.5, 0, -1, 12 * pulse);
  g.addColorStop(0, 'rgba(210, 250, 255, 0.95)');
  g.addColorStop(0.3, 'rgba(103, 220, 245, 0.55)');
  g.addColorStop(1, 'rgba(40, 140, 180, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, -1, 12 * pulse, 0, TAU);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = '#24424f';
  ctx.beginPath();
  ctx.arc(0, -1, 6.2, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = accent;
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.arc(0, -1, 6.2, 0, TAU);
  ctx.stroke();
  ctx.fillStyle = '#c8f8ff';
  ctx.beginPath();
  ctx.arc(0, -1, 2.7, 0, TAU);
  ctx.fill();

  // dish arms
  ctx.save();
  ctx.rotate(ang);
  ctx.strokeStyle = '#84b7c4';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-9, 0);
  ctx.lineTo(9, 0);
  ctx.stroke();
  ctx.fillStyle = '#4b6d78';
  roundRect(ctx, 7, -3.5, 5, 7, 1.5);
  ctx.fill();
  ctx.fillStyle = accent;
  ctx.beginPath();
  ctx.arc(10, 0, 1.8, 0, TAU);
  ctx.fill();
  if (lvl >= 2) {
    ctx.strokeStyle = 'rgba(130, 235, 255, 0.55)';
    ctx.lineWidth = 0.9;
    ctx.beginPath();
    ctx.arc(0, 0, 12, -0.7, 0.7);
    ctx.stroke();
  }
  ctx.restore();

  if (lvl >= 3) {
    // satellite ring
    ctx.strokeStyle = 'rgba(130, 235, 255, 0.45)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(0, -1, 13, 4.8, time * 0.8, 0, TAU);
    ctx.stroke();
  }
}

function drawRocketPod(ctx, ang, tower, lvl, accent) {
  ctx.save();
  ctx.rotate(ang);
  const recoil = (tower.recoil || 0) * 2.5;
  // main pod
  ctx.fillStyle = '#4a443b';
  roundRect(ctx, -8 - recoil, -8.4, 19, 16.8, 3.4);
  ctx.fill();
  ctx.strokeStyle = '#7b7161';
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // tubes
  const cols = lvl >= 2 ? 3 : 2;
  const rows = lvl >= 3 ? 3 : 2;
  for (let cx = 0; cx < cols; cx++) {
    for (let cy = 0; cy < rows; cy++) {
      const tx = 8 - cols * 2.1 + cx * 4.2;
      const ty = -rows * 2 + cy * 4 + (rows === 3 ? -0.4 : 0.4);
      ctx.fillStyle = '#241f19';
      ctx.beginPath();
      ctx.arc(tx - recoil, ty, 1.65, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(255, 131, 71, 0.7)';
      ctx.beginPath();
      ctx.arc(tx - recoil, ty, 0.8, 0, TAU);
      ctx.fill();
    }
  }
  // targeting sensor
  ctx.fillStyle = accent;
  ctx.beginPath();
  ctx.arc(-1 - recoil, 0, 2, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 220, 170, 0.8)';
  ctx.beginPath();
  ctx.arc(-1 - recoil, 0, 0.7, 0, TAU);
  ctx.fill();
  // fins
  ctx.fillStyle = '#6f6555';
  ctx.beginPath();
  ctx.moveTo(-8, -8.4);
  ctx.lineTo(-13, -10.2);
  ctx.lineTo(-9.5, -5.2);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(-8, 8.4);
  ctx.lineTo(-13, 10.2);
  ctx.lineTo(-9.5, 5.2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawLaser(ctx, ang, tower, lvl, accent, time) {
  // tripod
  ctx.strokeStyle = '#686458';
  ctx.lineWidth = 2;
  for (let i = 0; i < 3; i++) {
    const a = i * (TAU / 3) + 0.3;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(a) * 9, Math.sin(a) * 9);
    ctx.stroke();
  }
  ctx.save();
  ctx.rotate(ang);
  // emitter housing
  ctx.fillStyle = '#3b3633';
  roundRect(ctx, -5, -5, 7, 10, 2.2);
  ctx.fill();
  // crystal
  const pulse = 0.85 + Math.sin(time * 5 + (tower.phase || 0)) * 0.15;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(0, 0, 0.5, 0, 0, 10 * pulse);
  g.addColorStop(0, 'rgba(255, 240, 220, 0.9)');
  g.addColorStop(0.35, 'rgba(255, 110, 92, 0.5)');
  g.addColorStop(1, 'rgba(255, 80, 60, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, 10 * pulse, 0, TAU);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = '#ff8c78';
  ctx.beginPath();
  ctx.moveTo(2, 0);
  ctx.lineTo(-1.8, -4.2);
  ctx.lineTo(-4.2, 0);
  ctx.lineTo(-1.8, 4.2);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#ffe7d8';
  ctx.beginPath();
  ctx.arc(0.3, -0.5, 1.2, 0, TAU);
  ctx.fill();
  // barrel
  ctx.fillStyle = '#8e877d';
  roundRect(ctx, 5, -1.9, 14, 3.8, 1.5);
  ctx.fill();
  ctx.fillStyle = '#c8c0b3';
  roundRect(ctx, 17.5, -2.3, 2.4, 4.6, 1);
  ctx.fill();
  if (lvl >= 2) {
    ctx.fillStyle = '#5f5950';
    roundRect(ctx, 7, -4.9, 9, 1.6, 0.8);
    ctx.fill();
    roundRect(ctx, 7, 3.3, 9, 1.6, 0.8);
    ctx.fill();
  }
  ctx.restore();

  // cooling ring
  ctx.strokeStyle = `rgba(255, 122, 100, ${0.2 + Math.sin(time * 2.4) * 0.08})`;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(0, 0, 12.5, 0, TAU);
  ctx.stroke();
}

function drawJedi(ctx, ang, tower, lvl, accent, time) {
  // robed figure
  ctx.fillStyle = '#2b3d4d';
  ctx.beginPath();
  ctx.arc(0, 0, 7.8, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#4c7b9e';
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = '#1c2c3a';
  ctx.beginPath();
  ctx.ellipse(-0.8, -0.8, 5.4, 4.6, 0, 0, TAU);
  ctx.fill();
  // hood
  ctx.fillStyle = '#314b60';
  ctx.beginPath();
  ctx.arc(0, -2.4, 3.9, Math.PI * 0.86, Math.PI * 2.14);
  ctx.fill();
  // sabers
  const spin = time * (lvl >= 3 ? 4.2 : 3.2) + (tower.phase || 0);
  const blades = lvl >= 4 ? 2 : 1;
  for (let b = 0; b < blades; b++) {
    const a = spin + b * Math.PI;
    ctx.save();
    ctx.rotate(a);
    ctx.strokeStyle = 'rgba(110, 205, 255, 0.18)';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(6, 0);
    ctx.lineTo(24, 0);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(125, 212, 255, 0.9)';
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(6, 0);
    ctx.lineTo(23, 0);
    ctx.stroke();
    ctx.strokeStyle = '#f0fbff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(7, 0);
    ctx.lineTo(23, 0);
    ctx.stroke();
    // hilt
    ctx.strokeStyle = '#aab6bf';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(2.5, 0);
    ctx.lineTo(6, 0);
    ctx.stroke();
    ctx.restore();
  }
  if (lvl >= 2) {
    ctx.strokeStyle = 'rgba(110, 200, 255, 0.22)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, 13.5, time * 0.7, time * 0.7 + 2.2);
    ctx.stroke();
  }
}

function drawBounty(ctx, ang, tower, lvl, accent, time) {
  ctx.save();
  ctx.rotate(ang);
  const recoil = (tower.recoil || 0) * 3;
  // cloak
  ctx.fillStyle = '#3f3a31';
  ctx.beginPath();
  ctx.ellipse(-3 - recoil, 0, 8.5, 7.6, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#6f6552';
  ctx.lineWidth = 1;
  ctx.stroke();
  // rifle
  ctx.fillStyle = '#2c2924';
  roundRect(ctx, 2 - recoil, -1.6, 23, 3.2, 1.2);
  ctx.fill();
  ctx.fillStyle = '#8e806b';
  roundRect(ctx, 18 - recoil, -2.2, 7.5, 4.4, 1.2);
  ctx.fill();
  ctx.fillStyle = '#5b5244';
  roundRect(ctx, 4 - recoil, -4.2, 7, 2, 0.8);
  ctx.fill();
  // scope glint
  const glint = 0.55 + Math.sin(time * 2.2 + (tower.phase || 0)) * 0.4;
  ctx.fillStyle = `rgba(255, 214, 130, ${glint})`;
  ctx.beginPath();
  ctx.arc(9 - recoil, -3.2, 1.3, 0, TAU);
  ctx.fill();
  // helmet
  ctx.fillStyle = '#6b5b49';
  ctx.beginPath();
  ctx.arc(1.5 - recoil, -0.5, 4.2, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#221e19';
  ctx.beginPath();
  ctx.arc(2.8 - recoil, -1.1, 2.3, -0.6, 1.2);
  ctx.fill();
  ctx.strokeStyle = accent;
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(-0.3 - recoil, 0.3);
  ctx.lineTo(3.5 - recoil, -0.2);
  ctx.stroke();
  ctx.restore();

  if (lvl >= 4) {
    ctx.strokeStyle = `rgba(255, 195, 110, ${0.16 + Math.sin(time * 2) * 0.05})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, TAU);
    ctx.stroke();
  }
}

/* ============================================================
   ENEMIES
   ============================================================ */

export function drawEnemy(ctx, e, time, S) {
  const def = ENEMY_TYPES[e.type];
  if (!def) return;
  const slow = e.slowT > 0;
  const flash = e.hitFlash > 0;

  ctx.save();
  ctx.translate(e.x, e.y);
  // shadow
  const bob = e.type === 'scout' ? Math.sin(time * 8 + e.phase) * 1.2 * S : 0;
  ctx.fillStyle = 'rgba(48, 29, 11, 0.28)';
  ctx.beginPath();
  ctx.ellipse(2 * S, (def.radius * 0.62 + 3) * S, def.radius * 0.95 * S, def.radius * 0.4 * S, 0, 0, TAU);
  ctx.fill();

  ctx.translate(0, bob);
  ctx.rotate(e.angle || 0);
  ctx.scale(S, S);

  if (e.type === 'droid') drawDroidBody(ctx, e, time, slow);
  else if (e.type === 'scout') drawScoutBody(ctx, e, time, slow);
  else if (e.type === 'tank') drawTankBody(ctx, e, time, slow);
  else if (e.type === 'boss') drawBossBody(ctx, e, time, slow);

  if (flash) {
    ctx.globalAlpha = 0.55 * Math.min(1, flash / 0.09);
    ctx.fillStyle = '#fff5e0';
    ctx.beginPath();
    ctx.arc(0, 0, def.radius * 0.9, 0, TAU);
    ctx.fill();
  }
  if (slow) {
    ctx.globalAlpha = 0.7;
    ctx.strokeStyle = 'rgba(110, 225, 255, 0.9)';
    ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.arc(0, 0, def.radius + 2.4, 0, TAU);
    ctx.stroke();
    for (let i = 0; i < 3; i++) {
      const a = time * 3 + i * 2.1 + (e.phase || 0);
      ctx.fillStyle = 'rgba(160, 240, 255, 0.8)';
      ctx.beginPath();
      ctx.arc(Math.cos(a) * (def.radius + 2), Math.sin(a) * (def.radius + 2), 0.9, 0, TAU);
      ctx.fill();
    }
  }
  ctx.restore();

  // health bar
  const showBar = e.hp < e.maxHp - 0.2 || e.type === 'boss';
  if (showBar) {
    const bw = (e.type === 'boss' ? 46 : Math.max(18, def.radius * 1.9)) * S;
    const bh = (e.type === 'boss' ? 4 : 2.6) * S;
    const bx = e.x - bw / 2;
    const by = e.y - (def.radius * S + 9 * S);
    ctx.fillStyle = 'rgba(25, 15, 8, 0.72)';
    roundRect(ctx, bx - 1, by - 1, bw + 2, bh + 2, 2);
    ctx.fill();
    const pct = clamp(e.hp / e.maxHp, 0, 1);
    const col = pct > 0.55 ? '#8fd45f' : pct > 0.25 ? '#e7b84c' : '#ef6a4f';
    ctx.fillStyle = col;
    roundRect(ctx, bx, by, Math.max(0.5, bw * pct), bh, 1.5);
    ctx.fill();
    if (e.type === 'boss') {
      ctx.fillStyle = 'rgba(255, 214, 150, 0.8)';
      ctx.fillRect(bx + bw * 0.5 - 0.5, by - 1, 1, bh + 2);
    }
  }
}

function drawDroidBody(ctx, e, time, slow) {
  const walk = Math.sin(time * 11 + (e.phase || 0)) * 0.8;
  // legs
  ctx.strokeStyle = '#7c6139';
  ctx.lineWidth = 1.6;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-3, -5);
  ctx.lineTo(-6 + walk, -9);
  ctx.moveTo(-3, 5);
  ctx.lineTo(-6 - walk, 9);
  ctx.moveTo(4, -5);
  ctx.lineTo(8 - walk * 0.5, -9);
  ctx.moveTo(4, 5);
  ctx.lineTo(8 + walk * 0.5, 9);
  ctx.stroke();
  // body
  const g = ctx.createLinearGradient(0, -8, 0, 8);
  g.addColorStop(0, '#e0c18b');
  g.addColorStop(0.55, '#c8a46a');
  g.addColorStop(1, '#9d7c4a');
  ctx.fillStyle = g;
  roundRect(ctx, -9, -6.5, 16, 13, 4);
  ctx.fill();
  ctx.strokeStyle = '#7f6238';
  ctx.lineWidth = 0.8;
  ctx.stroke();
  // chest plate
  ctx.fillStyle = '#a88755';
  roundRect(ctx, -5, -4.5, 8, 9, 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 235, 190, 0.4)';
  ctx.fillRect(-4, -3.4, 5, 1);
  // head
  ctx.fillStyle = '#d2b27d';
  roundRect(ctx, 5, -4, 8.5, 8, 3);
  ctx.fill();
  ctx.strokeStyle = '#7f6238';
  ctx.stroke();
  // eyes
  ctx.fillStyle = '#ff5c48';
  ctx.shadowColor = 'rgba(255, 80, 60, 0.8)';
  ctx.shadowBlur = 3;
  ctx.beginPath();
  ctx.arc(10, -2.3, 1.25, 0, TAU);
  ctx.arc(10, 2.3, 1.25, 0, TAU);
  ctx.fill();
  ctx.shadowBlur = 0;
  // antenna
  ctx.strokeStyle = '#9d7c4a';
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(7.5, -1.5);
  ctx.lineTo(4, -7);
  ctx.stroke();
}

function drawScoutBody(ctx, e, time, slow) {
  const flap = Math.sin(time * 12 + (e.phase || 0)) * 0.7;
  // thruster trail
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const tg = ctx.createLinearGradient(-8, 0, -27, 0);
  tg.addColorStop(0, 'rgba(160, 255, 110, 0.5)');
  tg.addColorStop(1, 'rgba(160, 255, 110, 0)');
  ctx.fillStyle = tg;
  ctx.beginPath();
  ctx.moveTo(-7, -3);
  ctx.lineTo(-27, 0);
  ctx.lineTo(-7, 3);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
  // hover bike
  ctx.fillStyle = '#4e5b56';
  roundRect(ctx, -10, -4.2, 19, 8.4, 3.5);
  ctx.fill();
  ctx.strokeStyle = '#87978e';
  ctx.lineWidth = 0.9;
  ctx.stroke();
  // side pods
  ctx.fillStyle = '#6d7c74';
  roundRect(ctx, -9, -8, 10, 3.2, 1.6);
  ctx.fill();
  roundRect(ctx, -9, 4.8, 10, 3.2, 1.6);
  ctx.fill();
  // rider
  ctx.fillStyle = '#3a413d';
  ctx.beginPath();
  ctx.ellipse(1, 0, 4.4, 3.6, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#23282a';
  ctx.beginPath();
  ctx.arc(4, 0, 2.7, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#a8ff6c';
  ctx.shadowColor = 'rgba(160, 255, 100, 0.85)';
  ctx.shadowBlur = 4;
  ctx.beginPath();
  ctx.arc(5.4, 0, 1.15, 0, TAU);
  ctx.fill();
  ctx.shadowBlur = 0;
  // fins
  ctx.strokeStyle = '#7f9188';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-8, -5);
  ctx.lineTo(-12 - flap, -7.5);
  ctx.moveTo(-8, 5);
  ctx.lineTo(-12 + flap, 7.5);
  ctx.stroke();
  // engine glows
  ctx.fillStyle = 'rgba(174, 255, 118, 0.85)';
  ctx.beginPath();
  ctx.arc(-9.5, -5, 1.3, 0, TAU);
  ctx.arc(-9.5, 5, 1.3, 0, TAU);
  ctx.fill();
}

function drawTankBody(ctx, e, time, slow) {
  const walk = Math.sin(time * 8 + (e.phase || 0)) * 1.1;
  // legs
  ctx.strokeStyle = '#5a3a2d';
  ctx.lineWidth = 2.4;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-4, -8);
  ctx.lineTo(-8 + walk, -13);
  ctx.moveTo(-4, 8);
  ctx.lineTo(-8 - walk, 13);
  ctx.moveTo(4, -8);
  ctx.lineTo(9, -13 + walk * 0.3);
  ctx.moveTo(4, 8);
  ctx.lineTo(9, 13 - walk * 0.3);
  ctx.stroke();
  // body
  const g = ctx.createLinearGradient(0, -11, 0, 11);
  g.addColorStop(0, '#b7765b');
  g.addColorStop(0.5, '#8d5341');
  g.addColorStop(1, '#63392d');
  ctx.fillStyle = g;
  roundRect(ctx, -13, -9.5, 22, 19, 4.5);
  ctx.fill();
  ctx.strokeStyle = '#4b2b22';
  ctx.lineWidth = 0.9;
  ctx.stroke();
  // shoulder plates
  ctx.fillStyle = '#a36950';
  roundRect(ctx, -6, -13, 10, 5, 2);
  ctx.fill();
  roundRect(ctx, -6, 8, 10, 5, 2);
  ctx.fill();
  // chest core
  ctx.fillStyle = '#40251d';
  roundRect(ctx, -3, -5.5, 10, 11, 2.5);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 122, 80, 0.85)';
  ctx.shadowColor = 'rgba(255, 90, 55, 0.9)';
  ctx.shadowBlur = 5;
  ctx.beginPath();
  ctx.arc(2, 0, 2.1, 0, TAU);
  ctx.fill();
  ctx.shadowBlur = 0;
  // head
  ctx.fillStyle = '#a56a51';
  roundRect(ctx, 7.5, -5, 8, 10, 3);
  ctx.fill();
  ctx.strokeStyle = '#5a3427';
  ctx.stroke();
  ctx.fillStyle = '#ff5f47';
  ctx.beginPath();
  ctx.arc(12, -2.3, 1.2, 0, TAU);
  ctx.arc(12, 2.3, 1.2, 0, TAU);
  ctx.fill();
  // cannon
  ctx.fillStyle = '#54463c';
  roundRect(ctx, 11, -1, 12, 2, 0.9);
  ctx.fill();
}

function drawBossBody(ctx, e, time, slow) {
  // treads
  ctx.fillStyle = '#332b26';
  roundRect(ctx, -27, -20, 44, 10, 4);
  ctx.fill();
  roundRect(ctx, -27, 10, 44, 10, 4);
  ctx.fill();
  // tread links
  ctx.strokeStyle = 'rgba(148, 122, 92, 0.5)';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 6; i++) {
    const tx = -23 + ((i * 8 + time * 26) % 36);
    ctx.beginPath();
    ctx.moveTo(tx, -19);
    ctx.lineTo(tx, -11);
    ctx.moveTo(tx, 11);
    ctx.lineTo(tx, 19);
    ctx.stroke();
  }
  // hull
  const g = ctx.createLinearGradient(0, -18, 0, 18);
  g.addColorStop(0, '#a0846c');
  g.addColorStop(0.45, '#775d49');
  g.addColorStop(1, '#4c392c');
  ctx.fillStyle = g;
  roundRect(ctx, -24, -16, 44, 32, 7);
  ctx.fill();
  ctx.strokeStyle = '#3a2b20';
  ctx.lineWidth = 1.4;
  ctx.stroke();
  // armor plates
  ctx.fillStyle = 'rgba(199, 169, 130, 0.35)';
  roundRect(ctx, -20, -12, 18, 7, 2);
  ctx.fill();
  roundRect(ctx, -20, 5, 18, 7, 2);
  ctx.fill();
  // turret
  ctx.fillStyle = '#6a5140';
  ctx.beginPath();
  ctx.arc(4, 0, 12.5, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#3f2f25';
  ctx.stroke();
  ctx.fillStyle = '#8d7159';
  ctx.beginPath();
  ctx.arc(4, 0, 8.5, 0, TAU);
  ctx.fill();
  // reactor core
  const pulse = 0.8 + Math.sin(time * 4 + (e.phase || 0)) * 0.2;
  ctx.fillStyle = 'rgba(255, 128, 59, 0.95)';
  ctx.shadowColor = 'rgba(255, 100, 40, 1)';
  ctx.shadowBlur = 12 * pulse;
  ctx.beginPath();
  ctx.arc(4, 0, 4.4, 0, TAU);
  ctx.fill();
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#ffe2b0';
  ctx.beginPath();
  ctx.arc(4, 0, 1.8, 0, TAU);
  ctx.fill();
  // barrels
  ctx.fillStyle = '#4b3a2d';
  roundRect(ctx, 13, -9, 18, 3.4, 1.5);
  ctx.fill();
  roundRect(ctx, 13, 5.6, 18, 3.4, 1.5);
  ctx.fill();
  // command antenna
  ctx.strokeStyle = '#c7a77e';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-4, -16);
  ctx.lineTo(-10, -25);
  ctx.stroke();
  ctx.fillStyle = '#ffb05e';
  ctx.beginPath();
  ctx.arc(-10, -25, 1.8, 0, TAU);
  ctx.fill();
}

/* ============================================================
   PROJECTILES & PARTICLES & EFFECTS
   ============================================================ */

export function drawProjectile(ctx, p, S) {
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(p.angle || 0);
  if (p.kind === 'bullet') {
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(255, 205, 100, 0.9)';
    ctx.lineWidth = 2.4;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(-9, 0);
    ctx.lineTo(2, 0);
    ctx.stroke();
    ctx.fillStyle = '#fff2c0';
    ctx.beginPath();
    ctx.arc(2, 0, 1.7, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 180, 80, 0.25)';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(-8, 0);
    ctx.lineTo(-2, 0);
    ctx.stroke();
  } else if (p.kind === 'rocket') {
    ctx.fillStyle = '#4e4a43';
    roundRect(ctx, -6, -2.2, 12, 4.4, 2);
    ctx.fill();
    ctx.fillStyle = '#d98d5a';
    ctx.beginPath();
    ctx.moveTo(5, -2.2);
    ctx.lineTo(9, 0);
    ctx.lineTo(5, 2.2);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#6d675c';
    ctx.beginPath();
    ctx.moveTo(-4, -2);
    ctx.lineTo(-7, -4);
    ctx.lineTo(-5, 0);
    ctx.lineTo(-7, 4);
    ctx.lineTo(-4, 2);
    ctx.closePath();
    ctx.fill();
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(-8, 0, 0, -8, 0, 8 * S);
    g.addColorStop(0, 'rgba(255, 230, 160, 1)');
    g.addColorStop(0.4, 'rgba(255, 140, 60, 0.8)');
    g.addColorStop(1, 'rgba(255, 80, 30, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(-8, 0, 8, 0, TAU);
    ctx.fill();
    ctx.restore();
  } else if (p.kind === 'ion') {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 13);
    g.addColorStop(0, 'rgba(230, 255, 255, 1)');
    g.addColorStop(0.28, 'rgba(120, 230, 255, 0.9)');
    g.addColorStop(1, 'rgba(50, 150, 210, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, 13, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(190, 250, 255, 0.75)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const a = p.spin + i * 2.1;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * 2, Math.sin(a) * 2);
      ctx.lineTo(Math.cos(a + 0.7) * 6, Math.sin(a + 0.7) * 6);
      ctx.lineTo(Math.cos(a + 1.1) * 4, Math.sin(a + 1.1) * 4);
      ctx.stroke();
    }
    ctx.restore();
  }
  ctx.restore();
}

export function drawParticles(ctx, particles) {
  ctx.save();
  for (const p of particles) {
    const life = p.life / p.max;
    if (life <= 0) continue;
    ctx.globalAlpha = Math.min(1, life * 1.4);
    if (p.glow) {
      ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.size * 3);
      g.addColorStop(0, p.color);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * 3, 0, TAU);
      ctx.fill();
    } else {
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = p.color;
      ctx.beginPath();
      if (p.square) {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot || 0);
        ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
        ctx.restore();
      } else {
        ctx.arc(p.x, p.y, p.size * Math.max(0.25, life), 0, TAU);
        ctx.fill();
      }
    }
  }
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = 1;
  ctx.restore();
}

export function drawEffects(ctx, effects, time) {
  for (const fx of effects) {
    const life = clamp(fx.life / fx.max, 0, 1);
    ctx.save();
    if (fx.kind === 'ring') {
      const t = 1 - life;
      const r = fx.r + (fx.maxR - fx.r) * (1 - Math.pow(1 - t, 2));
      ctx.globalAlpha = life * (fx.alpha ?? 0.8);
      ctx.strokeStyle = fx.color;
      ctx.lineWidth = Math.max(1, fx.width * life);
      ctx.beginPath();
      ctx.arc(fx.x, fx.y, r, 0, TAU);
      ctx.stroke();
      if (fx.fill) {
        const g = ctx.createRadialGradient(fx.x, fx.y, r * 0.2, fx.x, fx.y, r);
        g.addColorStop(0, 'rgba(255,255,255,0)');
        g.addColorStop(0.8, fx.fill);
        g.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(fx.x, fx.y, r, 0, TAU);
        ctx.fill();
      }
    } else if (fx.kind === 'beam') {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = life;
      ctx.strokeStyle = fx.color;
      ctx.lineCap = 'round';
      ctx.shadowColor = fx.color;
      ctx.shadowBlur = 12;
      ctx.lineWidth = fx.width * (0.5 + life * 0.5);
      ctx.beginPath();
      ctx.moveTo(fx.x1, fx.y1);
      ctx.lineTo(fx.x2, fx.y2);
      ctx.stroke();
      ctx.shadowBlur = 0;
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
      ctx.lineWidth = Math.max(1, fx.width * 0.25);
      ctx.beginPath();
      ctx.moveTo(fx.x1, fx.y1);
      ctx.lineTo(fx.x2, fx.y2);
      ctx.stroke();
    } else if (fx.kind === 'arc') {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = life;
      ctx.shadowColor = fx.color;
      ctx.shadowBlur = 10;
      ctx.strokeStyle = fx.color;
      ctx.lineWidth = fx.width || 2;
      ctx.beginPath();
      const pts = fx.points;
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,0.9)';
      ctx.lineWidth = 0.8;
      ctx.stroke();
    } else if (fx.kind === 'slash') {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = life * 0.8;
      ctx.strokeStyle = fx.color;
      ctx.lineWidth = fx.width || 3;
      ctx.shadowColor = fx.color;
      ctx.shadowBlur = 14;
      ctx.beginPath();
      ctx.arc(fx.x, fx.y, fx.r, fx.a0 + (1 - life) * 0.7, fx.a1 + (1 - life) * 0.7);
      ctx.stroke();
    } else if (fx.kind === 'flash') {
      ctx.globalAlpha = life * 0.55;
      const g = ctx.createRadialGradient(fx.x, fx.y, 0, fx.x, fx.y, fx.r);
      g.addColorStop(0, fx.color);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(fx.x, fx.y, fx.r, 0, TAU);
      ctx.fill();
    } else if (fx.kind === 'text') {
      ctx.globalAlpha = life;
      ctx.fillStyle = fx.color;
      ctx.font = `800 ${fx.size || 12}px "Trebuchet MS", sans-serif`;
      ctx.textAlign = 'center';
      ctx.fillText(fx.text, fx.x, fx.y - (1 - life) * 22);
    }
    ctx.restore();
  }
}

export function drawAura(ctx, tower, S, time) {
  const t = TOWERS[tower.type];
  if (!t) return;
  const r = tower.range || 86;
  ctx.save();
  ctx.globalAlpha = 0.5;
  const pulse = 1 + Math.sin(time * 2 + (tower.phase || 0)) * 0.02;
  const g = ctx.createRadialGradient(tower.x, tower.y, r * 0.2, tower.x, tower.y, r * pulse);
  g.addColorStop(0, 'rgba(110, 190, 255, 0.03)');
  g.addColorStop(0.8, 'rgba(90, 170, 255, 0.05)');
  g.addColorStop(1, 'rgba(90, 170, 255, 0.14)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(tower.x, tower.y, r * pulse, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(120, 200, 255, 0.22)';
  ctx.lineWidth = 1;
  ctx.setLineDash([2, 6]);
  ctx.lineDashOffset = time * 14;
  ctx.beginPath();
  ctx.arc(tower.x, tower.y, r, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

export function drawPreview(ctx, type, x, y, valid, time, S) {
  const def = TOWERS[type];
  if (!def) return;
  ctx.save();
  ctx.globalAlpha = 0.55;
  drawRange(ctx, x, y, def.range[0] * S, valid ? '#9ee6a3' : '#ff7766', 0.85);
  ctx.globalAlpha = 1;
  const fake = {
    x, y, type, level: 1, angle: -Math.PI / 2 + Math.sin(time * 0.8) * 0.25,
    recoil: 0, phase: 0,
  };
  if (!valid) {
    ctx.save();
    ctx.globalAlpha = 0.7;
    ctx.filter = 'sepia(0.5) saturate(1.4) hue-rotate(-30deg)';
    drawTower(ctx, fake, time, S, false, 0.85);
    ctx.filter = 'none';
    ctx.restore();
    // red slash mark
    ctx.strokeStyle = 'rgba(255, 90, 70, 0.9)';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(x - 8, y - 8);
    ctx.lineTo(x + 8, y + 8);
    ctx.moveTo(x + 8, y - 8);
    ctx.lineTo(x - 8, y + 8);
    ctx.stroke();
  } else {
    drawTower(ctx, fake, time, S, false, 0.8);
    ctx.strokeStyle = 'rgba(160, 240, 160, 0.65)';
    ctx.lineWidth = 1.3;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.arc(x, y, 21 * S, 0, TAU);
    ctx.stroke();
  }
  ctx.restore();
}

export function drawSpawnGlow(ctx, pathPts, time) {
  if (!pathPts.length) return;
  const [x, y] = pathPts[0];
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(x + 18, y, 0, x + 18, y, 70);
  g.addColorStop(0, 'rgba(255, 90, 70, 0.20)');
  g.addColorStop(1, 'rgba(255, 50, 30, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x + 18, y, 70, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawBuildFlash(ctx, x, y, time, S) {
  // reserved for placement flourish
  void ctx; void x; void y; void time; void S;
}

/* ============================================================
   Game simulation — path, towers, waves, combat, rendering
   ============================================================ */

import {
  TOWERS, TOWER_ORDER, TARGET_MODES, ENEMY_TYPES, TOTAL_WAVES,
  START_CREDITS, START_LIVES, DECOR, PATH_POINTS, makeWave, waveReward,
  enemyReward, towerLevel, sellValue, clamp,
} from './data.js';
import {
  buildBackground, drawBaseShield, drawTower, drawTowerShadow, drawRange,
  drawEnemy, drawProjectile, drawParticles, drawEffects, drawAura, drawPreview,
  drawSpawnGlow,
} from './art.js';

const TAU = Math.PI * 2;
const BASE = { x: 0.952, y: 0.60 };

function angleLerp(a, b, t) {
  let d = ((b - a + Math.PI) % TAU + TAU) % TAU - Math.PI;
  return a + d * Math.min(1, t);
}

function samplePath(points, w, h, per = 18) {
  const src = points.map(p => [p[0] * w, p[1] * h]);
  const out = [];
  for (let i = 0; i < src.length - 1; i++) {
    const p0 = src[Math.max(0, i - 1)];
    const p1 = src[i];
    const p2 = src[i + 1];
    const p3 = src[Math.min(src.length - 1, i + 2)];
    for (let s = 0; s < per; s++) {
      const t = s / per;
      const t2 = t * t;
      const t3 = t2 * t;
      const x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      const y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      out.push([x, y]);
    }
  }
  out.push(src[src.length - 1].slice());
  return out;
}

function pointDistanceToPath(x, y, pts) {
  let best = Infinity;
  for (let i = 0; i < pts.length - 1; i++) {
    const ax = pts[i][0], ay = pts[i][1];
    const bx = pts[i + 1][0], by = pts[i + 1][1];
    const dx = bx - ax, dy = by - ay;
    const l2 = dx * dx + dy * dy || 1;
    let t = ((x - ax) * dx + (y - ay) * dy) / l2;
    t = clamp(t, 0, 1);
    const px = ax + dx * t, py = ay + dy * t;
    const d = (x - px) ** 2 + (y - py) ** 2;
    if (d < best) best = d;
  }
  return Math.sqrt(best);
}

export class Game {
  constructor(canvas, audio, callbacks = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.audio = audio;
    this.callbacks = callbacks;
    this.dpr = 1;
    this.w = 1;
    this.h = 1;
    this.S = 1;
    this.pathPts = [];
    this.pathLen = 1;
    this.bg = null;
    this.time = 0;
    this.realTime = 0;
    this.started = false;
    this.paused = false;
    this.speed = 1;
    this.preview = null;
    this.pendingType = null;
    this.selected = null;
    this.shake = 0;
    this.baseFlash = 0;
    this.dustTimer = 0;
    this.uid = 1;
    this.reset();
    this.resize();
  }

  reset() {
    this.credits = START_CREDITS;
    this.lives = START_LIVES;
    this.waveNumber = 1;
    this.waveActive = false;
    this.spawnQueue = null;
    this.spawnTimer = 0;
    this.waveTotal = 0;
    this.waveSpawned = 0;
    this.enemies = [];
    this.towers = [];
    this.projectiles = [];
    this.particles = [];
    this.effects = [];
    this.kills = 0;
    this.creditsEarned = 0;
    this.selected = null;
    this.pendingType = null;
    this.preview = null;
    this.phase = 'build';
    this.endless = false;
    this.bossRef = null;
    this.shake = 0;
    this.baseFlash = 0;
    this.dustTimer = 0;
    this.spawnPoint = [0, 0];
  }

  resize(w, h, dpr) {
    this.dpr = dpr;
    this.w = Math.max(1, w);
    this.h = Math.max(1, h);
    this.canvas.width = Math.floor(this.w * dpr);
    this.canvas.height = Math.floor(this.h * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.S = clamp(Math.min(this.w / 960, this.h / 640), 0.58, 1.55);
    this.pathPts = samplePath(PATH_POINTS, this.w, this.h);
    let len = 0;
    for (let i = 1; i < this.pathPts.length; i++) {
      len += Math.hypot(this.pathPts[i][0] - this.pathPts[i - 1][0], this.pathPts[i][1] - this.pathPts[i - 1][1]);
    }
    this.pathLen = Math.max(1, len);
    this.spawnPoint = this.pathPts[0] || [0, 0];
    this.bg = buildBackground(this.w, this.h, this.pathPts, this.S, Math.min(dpr, 2));
    for (const t of this.towers) {
      t.x = t.nx * this.w;
      t.y = t.ny * this.h;
    }
    for (const e of this.enemies) {
      this.positionEnemy(e);
    }
  }

  begin() {
    if (this.started) return;
    this.started = true;
    this.phase = 'build';
    this.credits = START_CREDITS;
    this.lives = START_LIVES;
  }

  setSpeed(s) {
    this.speed = s;
  }

  /* ---------------- path & placement ---------------- */

  pathWidth() {
    return clamp(33 * this.S, 23, 52);
  }

  distanceToPath(x, y) {
    return pointDistanceToPath(x, y, this.pathPts);
  }

  canPlace(type, nx, ny) {
    const def = TOWERS[type];
    if (!def) return { ok: false, reason: 'Unknown tower' };
    if (!this.started) return { ok: false, reason: 'Deploy the outpost first' };
    if (this.phase === 'defeat' || this.phase === 'victory') return { ok: false, reason: 'Run over' };
    if (this.credits < def.cost) return { ok: false, reason: `Need ${def.cost - this.credits} more credits` };
    const x = nx * this.w;
    const y = ny * this.h;
    const S = this.S;
    const marginX = 20 * S;
    const top = Math.max(48, 40 * S);
    const bottom = this.h - 14 * S;
    if (x < marginX || x > this.w - marginX || y < top || y > bottom) {
      return { ok: false, reason: 'Too close to the edge' };
    }
    if (this.distanceToPath(x, y) < this.pathWidth() / 2 + 17 * S) {
      return { ok: false, reason: "Can't build on the droid route" };
    }
    const m = Math.min(this.w, this.h);
    for (const d of DECOR) {
      const dx = d.x * this.w;
      const dy = d.y * this.h;
      const dr = d.r * m;
      if (Math.hypot(x - dx, y - dy) < dr + 19 * S) {
        return { ok: false, reason: 'Obstructed — pick clear sand' };
      }
    }
    const baseX = BASE.x * this.w;
    const baseY = BASE.y * this.h;
    if (Math.hypot(x - baseX, y - baseY) < clamp(m * 0.085, 44, 96) + 16 * S) {
      return { ok: false, reason: 'Too close to the relay' };
    }
    for (const t of this.towers) {
      if (Math.hypot(x - t.x, y - t.y) < 31 * S) {
        return { ok: false, reason: 'Another tower is in the way' };
      }
    }
    return { ok: true, reason: '' };
  }

  placeTower(type, nx, ny) {
    const check = this.canPlace(type, nx, ny);
    if (!check.ok) return check;
    const def = TOWERS[type];
    const lv = towerLevel(type, 1);
    const tower = {
      id: this.uid++,
      type,
      nx, ny,
      x: nx * this.w,
      y: ny * this.h,
      level: 1,
      range: lv.range,
      damage: lv.damage,
      cooldown: lv.cooldown,
      cooldownLeft: 0.15,
      angle: -Math.PI / 2,
      targetAngle: -Math.PI / 2,
      recoil: 0,
      mode: 'first',
      spent: def.cost,
      phase: Math.random() * TAU,
      flash: 0,
    };
    this.credits -= def.cost;
    this.towers.push(tower);
    this.effects.push({ kind: 'ring', x: tower.x, y: tower.y, r: 6 * this.S, maxR: 38 * this.S, color: '#ffe6a6', width: 2.4 * this.S, life: 0.4, max: 0.4, alpha: 0.9 });
    this.spark(tower.x, tower.y, 10, '#ffd98a', 2.4);
    this.audio.place();
    return { ok: true, tower, reason: '' };
  }

  selectTower(tower) {
    if (!tower) { this.selected = null; return; }
    this.selected = tower;
    this.pendingType = null;
    this.preview = null;
  }

  towerAt(px, py) {
    for (let i = this.towers.length - 1; i >= 0; i--) {
      const t = this.towers[i];
      if (Math.hypot(px - t.x, py - t.y) < 27 * this.S) return t;
    }
    return null;
  }

  setPending(type) {
    this.pendingType = type;
    this.preview = null;
    if (type) this.selected = null;
  }

  setPreview(nx, ny) {
    if (!this.pendingType) { this.preview = null; return; }
    if (nx == null || ny == null) { this.preview = null; return; }
    const check = this.canPlace(this.pendingType, nx, ny);
    this.preview = { type: this.pendingType, nx, ny, valid: check.ok };
  }

  tryPlaceDefault(type, nx, ny) {
    const result = this.placeTower(type, nx, ny);
    if (result.ok) {
      this.pendingType = null;
      this.preview = null;
    }
    return result;
  }

  upgradeSelected() {
    const t = this.selected;
    if (!t || t.level >= 4) return { ok: false, reason: 'Already max level' };
    const lv = towerLevel(t.type, t.level);
    if (this.credits < lv.upgrade) return { ok: false, reason: `Need ${lv.upgrade - this.credits} more credits` };
    this.credits -= lv.upgrade;
    t.spent += lv.upgrade;
    t.level++;
    const next = towerLevel(t.type, t.level);
    t.range = next.range;
    t.damage = next.damage;
    t.cooldown = next.cooldown;
    t.flash = 1;
    this.effects.push({ kind: 'ring', x: t.x, y: t.y, r: 8 * this.S, maxR: 46 * this.S, color: '#8ff0ff', width: 2.5 * this.S, life: 0.5, max: 0.5 });
    this.effects.push({ kind: 'flash', x: t.x, y: t.y, r: 46 * this.S, color: 'rgba(130, 225, 255, 0.35)', life: 0.35, max: 0.35 });
    this.spark(t.x, t.y, 16, '#b9f4ff', 3);
    this.audio.upgrade();
    return { ok: true };
  }

  sellSelected() {
    const t = this.selected;
    if (!t) return { ok: false };
    const value = sellValue(t);
    this.credits += value;
    this.towers = this.towers.filter(x => x !== t);
    this.selected = null;
    this.effects.push({ kind: 'ring', x: t.x, y: t.y, r: 12 * this.S, maxR: 40 * this.S, color: '#ffce7a', width: 2, life: 0.45, max: 0.45 });
    this.effects.push({ kind: 'text', x: t.x, y: t.y - 10, text: `+${value}`, color: '#ffe2a0', size: 13 * this.S, life: 0.8, max: 0.8 });
    this.spark(t.x, t.y, 8, '#ffce7a', 2);
    this.audio.sell();
    return { ok: true, value };
  }

  cycleTarget() {
    if (!this.selected) return;
    const i = TARGET_MODES.findIndex(m => m.id === this.selected.mode);
    this.selected.mode = TARGET_MODES[(i + 1) % TARGET_MODES.length].id;
    this.audio.ui();
  }

  /* ---------------- waves ---------------- */

  startWave() {
    if (!this.started || this.paused || this.waveActive) return false;
    if (this.phase !== 'build') return false;
    const specs = makeWave(this.waveNumber);
    let last = 0;
    this.spawnQueue = specs.map(s => {
      const gap = Math.max(0.08, s.delay - last);
      last = s.delay;
      return { ...s, gap };
    });
    this.spawnTimer = this.spawnQueue.length ? this.spawnQueue[0].gap : 0.5;
    this.waveTotal = this.spawnQueue.length;
    this.waveSpawned = 0;
    this.waveActive = true;
    this.phase = 'wave';
    this.bossRef = null;
    this.audio.waveStart();
    this.effects.push({ kind: 'ring', x: this.w * 0.04, y: this.h * 0.64, r: 8 * this.S, maxR: 64 * this.S, color: '#ff8a63', width: 2, life: 0.7, max: 0.7 });
    this.callbacks.onWaveStart?.(this.waveNumber);
    if (this.waveNumber === TOTAL_WAVES && !this.endless) {
      this.callbacks.toast?.('Final wave — hold the relay!', 'bad');
    } else if (this.waveNumber % 10 === 0) {
      this.callbacks.toast?.('Command droid inbound', 'bad');
    }
    return true;
  }

  spawnEnemy(spec) {
    const def = ENEMY_TYPES[spec.type];
    const e = {
      id: this.uid++,
      type: spec.type,
      hp: spec.hp,
      maxHp: spec.hp,
      speed: spec.speed * (0.95 + Math.random() * 0.1),
      t: 0,
      x: this.pathPts[0][0],
      y: this.pathPts[0][1],
      angle: 0,
      radius: def.radius,
      slowT: 0,
      slowFactor: 0,
      hitFlash: 0,
      phase: Math.random() * TAU,
      dead: false,
      reward: enemyReward(spec.type, this.waveNumber),
      leak: def.leak,
      isBoss: spec.type === 'boss',
    };
    this.positionEnemy(e);
    this.enemies.push(e);
    this.waveSpawned++;
    if (e.isBoss) {
      this.bossRef = e;
      this.audio.bossWarn();
      this.shake = Math.max(this.shake, 5);
      this.callbacks.onBoss?.();
      this.callbacks.toast?.('Droid commander on the field', 'bad');
      this.effects.push({ kind: 'ring', x: e.x, y: e.y, r: 10 * this.S, maxR: 90 * this.S, color: '#ff8a63', width: 3, life: 0.7, max: 0.7 });
    }
  }

  positionEnemy(e) {
    const n = this.pathPts.length;
    if (!n) return;
    const f = clamp(e.t, 0, 1) * (n - 1);
    const i0 = Math.min(n - 1, Math.floor(f));
    const i1 = Math.min(n - 1, i0 + 1);
    const frac = f - i0;
    const a = this.pathPts[i0];
    const b = this.pathPts[i1];
    e.x = a[0] + (b[0] - a[0]) * frac;
    e.y = a[1] + (b[1] - a[1]) * frac;
    e.angle = Math.atan2(b[1] - a[1], b[0] - a[0]);
  }

  completeWave() {
    if (!this.waveActive) return;
    this.waveActive = false;
    this.spawnQueue = null;
    const bonus = waveReward(this.waveNumber);
    this.credits += bonus;
    this.creditsEarned += bonus;
    this.audio.waveClear();
    this.callbacks.toast?.(`Wave ${this.waveNumber} cleared  +${bonus} credits`, 'good');
    this.effects.push({ kind: 'ring', x: BASE.x * this.w, y: BASE.y * this.h, r: 12 * this.S, maxR: 90 * this.S, color: '#8ff0b0', width: 2, life: 0.8, max: 0.8 });

    if (!this.endless && this.waveNumber >= TOTAL_WAVES) {
      this.win();
      return;
    }
    this.waveNumber++;
    this.phase = 'build';
    this.selected = null;
    this.callbacks.onWaveClear?.(this.waveNumber, bonus);
  }

  win() {
    if (this.phase === 'victory') return;
    this.phase = 'victory';
    this.waveActive = false;
    this.audio.victory();
    this.callbacks.onEnd?.(true);
  }

  defeat() {
    if (this.phase === 'defeat') return;
    this.phase = 'defeat';
    this.waveActive = false;
    this.audio.defeat();
    this.shake = 16;
    this.callbacks.onEnd?.(false);
  }

  continueEndless() {
    this.endless = true;
    this.phase = 'build';
    if (this.waveNumber <= TOTAL_WAVES) this.waveNumber = TOTAL_WAVES + 1;
    this.lives = Math.max(this.lives, 10);
    this.selected = null;
    this.paused = false;
    this.callbacks.toast?.('Endless mode — the droid army is endless too', 'bad');
  }

  /* ---------------- update ---------------- */

  update(rawDt) {
    const rdt = Math.min(rawDt, 0.05);
    this.realTime += rdt;
    if (!this.started || this.paused || this.phase === 'victory' || this.phase === 'defeat') {
      this.updateFx(rdt);
      return;
    }
    const dt = rdt * this.speed;
    this.time += dt;

    // ambient dust
    this.dustTimer -= dt;
    if (this.dustTimer <= 0) {
      this.dustTimer = 0.35 + Math.random() * 0.5;
      if (this.particles.length < 260) {
        this.particles.push({
          x: Math.random() * this.w,
          y: this.h * (0.25 + Math.random() * 0.7),
          vx: (10 + Math.random() * 26) * this.S,
          vy: (2 + Math.random() * 8) * this.S,
          life: 3.5 + Math.random() * 4,
          max: 7,
          size: (0.7 + Math.random() * 1.2) * this.S,
          color: 'rgba(255, 233, 185, 0.35)',
          glow: false,
          gravity: 0,
          drag: 0.99,
        });
      }
    }

    if (this.waveActive && this.spawnQueue) {
      this.spawnTimer -= dt;
      let guard = 0;
      while (this.spawnTimer <= 0 && this.spawnQueue.length && guard++ < 20) {
        const spec = this.spawnQueue.shift();
        this.spawnEnemy(spec);
        this.spawnTimer += this.spawnQueue.length ? this.spawnQueue[0].gap : 0.5;
      }
    }

    this.updateEnemies(dt);
    this.updateTowers(dt);
    this.updateProjectiles(dt);
    this.updateFx(dt);
    this.cleanup();

    if (this.waveActive && (!this.spawnQueue || this.spawnQueue.length === 0) && this.enemies.length === 0) {
      this.completeWave();
    }
    if (this.baseFlash > 0) this.baseFlash = Math.max(0, this.baseFlash - dt * 2);
    if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 34);
  }

  updateFx(dt) {
    for (const e of this.effects) e.life -= dt;
    for (const p of this.particles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      if (p.gravity) p.vy += p.gravity * dt;
      if (p.drag) { p.vx *= p.drag; p.vy *= p.drag; }
    }
    this.effects = this.effects.filter(e => e.life > 0);
    this.particles = this.particles.filter(p => p.life > 0 && p.x > -80 && p.x < this.w + 80 && p.y > -80 && p.y < this.h + 80);
  }

  updateEnemies(dt) {
    for (const e of this.enemies) {
      if (e.dead) continue;
      if (e.hitFlash > 0) e.hitFlash = Math.max(0, e.hitFlash - dt);
      if (e.slowT > 0) {
        e.slowT -= dt;
        if (e.slowT <= 0) { e.slowT = 0; e.slowFactor = 0; }
      }
      const slowMul = e.slowT > 0 ? 1 - e.slowFactor : 1;
      const pxPerSec = e.speed * this.S * slowMul;
      e.t += (pxPerSec * dt) / this.pathLen;
      if (e.t >= 1) {
        e.dead = true;
        this.leakEnemy(e);
      } else {
        this.positionEnemy(e);
      }
    }
  }

  leakEnemy(e) {
    this.lives -= e.leak;
    this.baseFlash = 1;
    this.shake = Math.max(this.shake, 8);
    this.audio.leak();
    this.effects.push({ kind: 'ring', x: BASE.x * this.w, y: BASE.y * this.h, r: 20 * this.S, maxR: 105 * this.S, color: '#ff6e58', width: 3, life: 0.7, max: 0.7 });
    this.effects.push({ kind: 'flash', x: BASE.x * this.w, y: BASE.y * this.h, r: 100 * this.S, color: 'rgba(255, 90, 70, 0.5)', life: 0.5, max: 0.5 });
    this.callbacks.toast?.(`Relay hit!  −${e.leak} integrity`, 'bad');
    this.callbacks.onLeak?.(e.leak);
    if (this.bossRef === e) this.bossRef = null;
    if (this.lives <= 0) {
      this.lives = 0;
      this.defeat();
    }
    if (this.phase === 'defeat') {
      // let the current frame finish; game over overlay takes over
    }
  }

  updateTowers(dt) {
    for (const t of this.towers) {
      if (t.flash > 0) t.flash = Math.max(0, t.flash - dt * 3);
      t.cooldownLeft -= dt;
      t.recoil = Math.max(0, t.recoil - dt * 7);
      const target = this.pickTarget(t);
      if (target) {
        const desired = Math.atan2(target.y - t.y, target.x - t.x);
        t.targetAngle = desired;
        t.angle = angleLerp(t.angle, desired, dt * 16);
        if (t.cooldownLeft <= 0) {
          this.fire(t, target);
          t.cooldownLeft = t.cooldown;
        }
      } else {
        t.targetAngle = t.angle;
        t.angle += dt * 0.18;
      }
    }
  }

  pickTarget(t) {
    const R2 = (t.range * this.S) ** 2;
    let best = null;
    let bestScore = -Infinity;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d2 = (e.x - t.x) ** 2 + (e.y - t.y) ** 2;
      if (d2 > R2) continue;
      let score;
      if (t.mode === 'first') score = e.t;
      else if (t.mode === 'last') score = -e.t;
      else if (t.mode === 'strong') score = e.hp;
      else score = -d2;
      if (score > bestScore) { bestScore = score; best = e; }
    }
    return best;
  }

  muzzle(t, target) {
    const a = Math.atan2(target.y - t.y, target.x - t.x);
    const d = (t.type === 'bounty' ? 23 : 17) * this.S;
    return { x: t.x + Math.cos(a) * d, y: t.y + Math.sin(a) * d, angle: a };
  }

  fire(t, target) {
    const def = TOWERS[t.type];
    const muzzle = this.muzzle(t, target);
    t.recoil = 1;
    t.flash = 0.4;
    if (def.attack === 'bullet') {
      this.projectiles.push({
        kind: 'bullet', x: muzzle.x, y: muzzle.y, target,
        speed: def.projectileSpeed * this.S, damage: t.damage,
        towerType: t.type, life: 2.4, angle: muzzle.angle,
      });
      this.audio.shot('scout');
      this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 11 * this.S, color: 'rgba(255, 220, 130, 0.55)', life: 0.08, max: 0.08 });
      this.spark(muzzle.x, muzzle.y, 2, '#ffd77f', 1.6);
    } else if (def.attack === 'rocket') {
      this.projectiles.push({
        kind: 'rocket', x: muzzle.x, y: muzzle.y, target,
        speed: def.projectileSpeed * this.S, damage: t.damage,
        splash: t.splash * this.S, towerType: t.type, life: 3.4, angle: muzzle.angle, source: { x: t.x, y: t.y },
      });
      this.audio.shot('rocket');
      this.spark(muzzle.x, muzzle.y, 4, '#ffb066', 2.2);
    } else if (def.attack === 'ion') {
      this.projectiles.push({
        kind: 'ion', x: muzzle.x, y: muzzle.y, target,
        speed: def.projectileSpeed * this.S, damage: t.damage,
        slow: t.slow, slowDuration: t.slowDuration, splash: 36 * this.S,
        towerType: t.type, life: 3, angle: muzzle.angle, spin: 0,
        source: { x: t.x, y: t.y },
      });
      this.audio.shot('ion');
      this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 16 * this.S, color: 'rgba(130, 230, 255, 0.6)', life: 0.14, max: 0.14 });
    } else if (def.attack === 'laser') {
      const hits = [target];
      const extra = (t.chain || 1) - 1;
      if (extra > 0) {
        const near = this.enemies
          .filter(e => !e.dead && e !== target && Math.hypot(e.x - target.x, e.y - target.y) < 95 * this.S && Math.hypot(e.x - t.x, e.y - t.y) < t.range * this.S)
          .sort((a, b) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(b.x - target.x, b.y - target.y));
        for (let i = 0; i < extra && i < near.length; i++) hits.push(near[i]);
      }
      let fx = muzzle;
      for (const e of hits) {
        this.effects.push({ kind: 'beam', x1: fx.x, y1: fx.y, x2: e.x, y2: e.y, color: '#ff6252', width: 3.1 * this.S, life: 0.11, max: 0.11 });
        this.damageEnemy(e, t.damage, { tower: t });
        this.spark(e.x, e.y, 3, '#ffab7f', 2.4);
        fx = { x: e.x, y: e.y };
      }
      this.audio.shot('laser');
      this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 14 * this.S, color: 'rgba(255, 110, 90, 0.5)', life: 0.1, max: 0.1 });
    } else if (def.attack === 'sniper') {
      const bonus = target.type === 'boss' ? def.bossBonus : 1;
      const dmg = t.damage * bonus;
      this.effects.push({ kind: 'beam', x1: muzzle.x, y1: muzzle.y, x2: target.x, y2: target.y, color: '#ffce7c', width: 2.2 * this.S, life: 0.16, max: 0.16 });
      this.effects.push({ kind: 'flash', x: target.x, y: target.y, r: 22 * this.S, color: 'rgba(255, 220, 150, 0.55)', life: 0.18, max: 0.18 });
      this.damageEnemy(target, dmg, { tower: t });
      this.spark(target.x, target.y, 8, '#ffd98a', 2.8);
      this.audio.shot('sniper');
      this.shake = Math.max(this.shake, target.type === 'boss' ? 2.5 : 0.7);
    } else if (def.attack === 'aura') {
      const R2 = (t.range * this.S) ** 2;
      let hurt = 0;
      for (const e of this.enemies) {
        if (e.dead) continue;
        if ((e.x - t.x) ** 2 + (e.y - t.y) ** 2 < R2) {
          this.damageEnemy(e, t.damage, { tower: t });
          hurt++;
        }
      }
      const slashAngle = this.time * 3 + t.phase;
      this.effects.push({ kind: 'slash', x: t.x, y: t.y, r: t.range * this.S * 0.92, a0: slashAngle, a1: slashAngle + 1.9, color: '#8fd6ff', width: 3 * this.S, life: 0.16, max: 0.16 });
      if (hurt > 0) this.audio.shot('jedi');
    }
  }

  damageEnemy(e, amount, opts = {}) {
    if (e.dead) return;
    const def = ENEMY_TYPES[e.type];
    let dmg = amount;
    if (!opts.trueDamage) dmg = Math.max(1, dmg - (def.armor || 0));
    e.hp -= dmg;
    e.hitFlash = 0.1;
    if (e.hp <= 0) this.killEnemy(e, opts.tower);
  }

  killEnemy(e, tower) {
    if (e.dead) return;
    e.dead = true;
    this.kills++;
    this.credits += e.reward;
    this.creditsEarned += e.reward;
    const big = e.type === 'boss' || e.type === 'tank';
    this.audio.kill(big);
    this.spark(e.x, e.y, big ? 14 : 7, e.type === 'scout' ? '#b4ff86' : '#ffb36b', big ? 3 : 2);
    if (e.type === 'boss') {
      this.explosion(e.x, e.y, 100 * this.S, true);
      this.shake = Math.max(this.shake, 12);
      this.effects.push({ kind: 'text', x: e.x, y: e.y - 20 * this.S, text: `+${e.reward}`, color: '#ffe6a1', size: 16 * this.S, life: 1.1, max: 1.1 });
      this.callbacks.toast?.(`Droid commander destroyed  +${e.reward} credits`, 'good');
      this.bossRef = null;
    } else if (e.type === 'tank') {
      this.explosion(e.x, e.y, 26 * this.S, false);
    } else {
      this.effects.push({ kind: 'ring', x: e.x, y: e.y, r: 2, maxR: 14 * this.S, color: 'rgba(255, 190, 110, 0.7)', width: 1.2, life: 0.25, max: 0.25, alpha: 0.5 });
    }
    // gold flecks
    this.spark(e.x, e.y, 3, '#ffe08a', 1.5);
    void tower;
  }

  explosion(x, y, radius, big) {
    this.effects.push({
      kind: 'ring', x, y, r: radius * 0.12, maxR: radius,
      color: big ? '#ffd08a' : '#ffb56b', width: big ? 4 : 2.4,
      life: big ? 0.6 : 0.32, max: big ? 0.6 : 0.32, fill: 'rgba(255, 120, 50, 0.18)',
    });
    this.effects.push({ kind: 'flash', x, y, r: radius * 0.7, color: big ? 'rgba(255, 210, 140, 0.6)' : 'rgba(255, 170, 100, 0.45)', life: big ? 0.3 : 0.16, max: big ? 0.3 : 0.16 });
    const n = big ? 28 : 12;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      const sp = (big ? 40 : 25) + Math.random() * (big ? 140 : 70);
      const size = (1 + Math.random() * (big ? 3.2 : 2.2)) * this.S;
      const life = 0.35 + Math.random() * (big ? 0.7 : 0.35);
      this.particles.push({
        x, y,
        vx: Math.cos(a) * sp * this.S, vy: Math.sin(a) * sp * this.S,
        life, max: life, size,
        color: i % 3 === 0 ? '#ffe8b0' : i % 3 === 1 ? '#ff9a55' : '#8b4e2f',
        glow: i % 3 !== 2, gravity: big ? 40 : 30, drag: 0.975,
      });
    }
    for (let i = 0; i < (big ? 8 : 4); i++) {
      const life = 0.6 + Math.random() * 0.6;
      this.particles.push({
        x: x + (Math.random() - 0.5) * radius * 0.5,
        y: y + (Math.random() - 0.5) * radius * 0.5,
        vx: (Math.random() - 0.5) * 18 * this.S,
        vy: -12 * this.S - Math.random() * 18 * this.S,
        life, max: life, size: (5 + Math.random() * 8) * this.S,
        color: 'rgba(73, 54, 38, 0.45)', glow: false, gravity: -4, drag: 0.985,
      });
    }
    this.audio.explosion(big);
  }

  spark(x, y, count, color, size) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * TAU;
      const sp = 20 + Math.random() * 100;
      const life = 0.2 + Math.random() * 0.35;
      this.particles.push({
        x, y,
        vx: Math.cos(a) * sp * this.S,
        vy: Math.sin(a) * sp * this.S,
        life, max: life,
        size: (size * (0.5 + Math.random() * 0.8)) * this.S,
        color, glow: true, gravity: 130, drag: 0.94,
      });
    }
  }

  ionBurst(x, y, radius, source) {
    const segments = 7;
    for (const other of this.enemies) {
      if (other.dead) continue;
      if (Math.hypot(other.x - x, other.y - y) < radius + other.radius * this.S) {
        this.slowEnemy(other, 0.55, 1.4);
        this.spark(other.x, other.y, 3, '#8cecff', 2);
      }
    }
    if (source) {
      const pts = [];
      for (let i = 0; i <= segments; i++) {
        const t = i / segments;
        const px = source.x + (x - source.x) * t;
        const py = source.y + (y - source.y) * t;
        const jitter = i === 0 || i === segments ? 0 : (Math.random() - 0.5) * 22 * this.S;
        pts.push([px + jitter, py + jitter * 0.6]);
      }
      this.effects.push({ kind: 'arc', points: pts, color: '#7fe6ff', width: 1.7 * this.S, life: 0.2, max: 0.2 });
    }
    this.effects.push({ kind: 'ring', x, y, r: 4, maxR: radius, color: '#8deaff', width: 2, life: 0.35, max: 0.35 });
    this.effects.push({ kind: 'flash', x, y, r: radius * 0.8, color: 'rgba(120, 230, 255, 0.4)', life: 0.2, max: 0.2 });
  }

  slowEnemy(e, factor, duration) {
    if (factor >= e.slowFactor || e.slowT <= 0) {
      e.slowFactor = Math.max(e.slowFactor, factor);
    }
    e.slowT = Math.max(e.slowT, duration);
  }

  updateProjectiles(dt) {
    for (const p of this.projectiles) {
      if (p.dead) continue;
      p.life -= dt;
      if (p.life <= 0) { p.dead = true; continue; }
      if (p.kind === 'ion') p.spin += dt * 9;
      const target = p.target;
      if (target && !target.dead) {
        const dx = target.x - p.x;
        const dy = target.y - p.y;
        const d = Math.hypot(dx, dy);
        p.angle = Math.atan2(dy, dx);
        const step = p.speed * dt;
        if (d <= step + target.radius * this.S * 0.8 + 4) {
          this.projectileHit(p, target);
          p.dead = true;
          continue;
        }
        p.x += (dx / d) * step;
        p.y += (dy / d) * step;
        if (p.kind === 'rocket') {
          const life = 0.3 + Math.random() * 0.25;
          this.particles.push({
            x: p.x - Math.cos(p.angle) * 7 * this.S,
            y: p.y - Math.sin(p.angle) * 7 * this.S,
            vx: (Math.random() - 0.5) * 12 * this.S,
            vy: (Math.random() - 0.5) * 12 * this.S - 4 * this.S,
            life, max: life, size: (2 + Math.random() * 2.2) * this.S,
            color: 'rgba(150, 142, 128, 0.4)', glow: false, gravity: -6, drag: 0.98,
          });
        }
      } else {
        const step = p.speed * dt;
        p.x += Math.cos(p.angle) * step;
        p.y += Math.sin(p.angle) * step;
        if (p.splash && target) {
          // payload falls short but still detonates
          this.projectileHit(p, null);
          p.dead = true;
        }
      }
    }
    this.projectiles = this.projectiles.filter(p => !p.dead);
  }

  projectileHit(p, target) {
    if (p.kind === 'bullet') {
      if (target) {
        this.damageEnemy(target, p.damage);
        this.spark(target.x, target.y, 3, '#ffd480', 2);
      }
    } else if (p.kind === 'rocket') {
      const R = p.splash;
      for (const e of this.enemies) {
        if (e.dead) continue;
        const d = Math.hypot(e.x - p.x, e.y - p.y);
        if (d < R + e.radius * this.S) {
          const falloff = 1 - clamp((d - e.radius * this.S) / R, 0, 1) * 0.45;
          this.damageEnemy(e, p.damage * falloff);
        }
      }
      this.explosion(p.x, p.y, R, false);
      this.shake = Math.max(this.shake, 1.8);
    } else if (p.kind === 'ion') {
      if (target) this.damageEnemy(target, p.damage);
      for (const e of this.enemies) {
        if (e.dead) continue;
        const d = Math.hypot(e.x - p.x, e.y - p.y);
        if (d < p.splash + e.radius * this.S) {
          this.slowEnemy(e, p.slow, p.slowDuration);
          if (e !== target) this.damageEnemy(e, p.damage * 0.35);
        }
      }
      this.ionBurst(p.x, p.y, p.splash, p.source);
      this.audio.shot('ion');
    }
  }

  cleanup() {
    this.enemies = this.enemies.filter(e => !e.dead);
    if (this.bossRef && this.bossRef.dead) this.bossRef = null;
    if (this.selected && !this.towers.includes(this.selected)) this.selected = null;
  }

  bossInfo() {
    let boss = null;
    for (const e of this.enemies) {
      if (e.type === 'boss' && !e.dead && (!boss || e.hp > boss.hp)) boss = e;
    }
    if (!boss) return null;
    return {
      name: this.waveNumber >= TOTAL_WAVES ? 'TACTICAL DROID COMMANDER' : 'DROID COMMANDER',
      pct: clamp(boss.hp / boss.maxHp, 0, 1),
      hp: Math.max(0, Math.ceil(boss.hp)),
    };
  }

  hud() {
    let queue = this.spawnQueue ? this.spawnQueue.length : 0;
    let alive = this.enemies.length;
    let progress = 0;
    if (this.phase === 'wave' && this.waveTotal > 0) {
      progress = clamp(1 - (queue + alive) / this.waveTotal, 0, 1);
    } else if (this.phase === 'build' && this.waveNumber > 1) {
      progress = 1;
    }
    return {
      credits: this.credits,
      lives: this.lives,
      wave: this.waveNumber,
      waveActive: this.waveActive,
      phase: this.phase,
      queue,
      alive,
      progress,
      endless: this.endless,
      boss: this.bossInfo(),
    };
  }

  /* ---------------- render ---------------- */

  render() {
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, this.w, this.h);

    let sx = 0, sy = 0;
    if (this.shake > 0.1) {
      sx = (Math.random() - 0.5) * this.shake;
      sy = (Math.random() - 0.5) * this.shake * 0.7;
    }
    ctx.save();
    ctx.translate(sx, sy);

    if (this.bg) ctx.drawImage(this.bg, 0, 0, this.w, this.h);
    else {
      ctx.fillStyle = '#c69a63';
      ctx.fillRect(0, 0, this.w, this.h);
    }

    drawSpawnGlow(ctx, this.pathPts, this.realTime);
    drawBaseShield(ctx, this.w, this.h, this.realTime, this.baseFlash);

    // range circles
    if (this.selected) {
      const t = this.selected;
      const color = t.type === 'ion' ? '#6fe1ff' : t.type === 'jedi' ? '#7cc7ff' : '#f1c76f';
      drawRange(ctx, t.x, t.y, t.range * this.S, color, 0.85);
    }
    for (const t of this.towers) {
      if (t.type === 'jedi') drawAura(ctx, t, this.S, this.realTime);
    }

    // enemies
    for (const e of this.enemies) {
      if (!e.dead) drawEnemy(ctx, e, this.realTime, this.S);
    }

    // tower shadows then towers
    for (const t of this.towers) drawTowerShadow(ctx, t, this.S);
    for (const t of this.towers) {
      drawTower(ctx, t, this.realTime, this.S, this.selected === t, 1);
    }

    // projectiles
    for (const p of this.projectiles) drawProjectile(ctx, p, this.S);

    // particles / effects
    drawParticles(ctx, this.particles);
    drawEffects(ctx, this.effects, this.realTime);

    // placement preview
    if (this.preview && this.pendingType) {
      drawPreview(ctx, this.preview.type, this.preview.nx * this.w, this.preview.ny * this.h, this.preview.valid, this.realTime, this.S);
    }

    // base flash wash
    if (this.baseFlash > 0.02) {
      ctx.save();
      ctx.globalAlpha = this.baseFlash * 0.18;
      ctx.fillStyle = '#ff5a3c';
      ctx.fillRect(0, 0, this.w, this.h);
      ctx.restore();
    }
    ctx.restore();
  }

  cardIcon(type) {
    return TOWERS[type]?.icon || '';
  }
}

export { TOWER_ORDER };

/* ============================================================
   UI wiring, drag & drop, input, loop
   ============================================================ */

import { TOWERS, TOWER_ORDER, TARGET_MODES, TOTAL_WAVES, waveReward, towerLevel, sellValue } from './data.js';
import { Game } from './game.js';
import { AudioEngine } from './audio.js';

const $ = (sel) => document.querySelector(sel);
const canvas = $('#game');
const stage = $('#stage');
const shop = $('#shop');
const towerList = $('#towerList');
const buildPanel = $('#buildPanel');
const inspectPanel = $('#inspectPanel');
const placeHint = $('#placeHint');
const dragGhost = $('#dragGhost');
const startScreen = $('#startScreen');
const endScreen = $('#endScreen');
const pauseModal = $('#pauseModal');

const audio = new AudioEngine();
let game;
let selectedType = null;
let ghostVisible = false;
let activeCard = null;
let bestWave = Number(localStorage.getItem('to-best') || 0);

const callbacks = {
  toast: (message, type) => toast(message, type),
  onWaveStart: () => syncUI(true),
  onWaveClear: () => syncUI(true),
  onBoss: () => syncUI(true),
  onEnd: (win) => finishRun(win),
};

game = new Game(canvas, audio, callbacks);
window.__game = game;

/* ---------------- helpers ---------------- */

const COIN = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l8.5 5v10L12 22l-8.5-5V7z" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M12 7v10M9 9h6M9 15h6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';

function fmt(n) {
  return Math.round(n).toLocaleString('en-US');
}

function cardPointers() {
  const rect = canvas.getBoundingClientRect();
  return rect;
}

function pointToMap(clientX, clientY) {
  const r = canvas.getBoundingClientRect();
  const px = clientX - r.left;
  const py = clientY - r.top;
  return {
    px, py,
    nx: px / Math.max(1, r.width),
    ny: py / Math.max(1, r.height),
    inside: px >= 0 && py >= 0 && px <= r.width && py <= r.height,
  };
}

let toastTimer = 0;
function toast(message, type = '') {
  const wrap = $('#toasts');
  const key = message + type;
  const now = performance.now();
  const existing = [...wrap.children].find(el => el.dataset.key === key);
  if (existing && now - toastTimer < 500) return;
  toastTimer = now;
  const el = document.createElement('div');
  el.className = `toast ${type}`;
  el.dataset.key = key;
  el.textContent = message;
  wrap.appendChild(el);
  while (wrap.children.length > 3) wrap.removeChild(wrap.firstChild);
  setTimeout(() => {
    el.classList.add('out');
    setTimeout(() => el.remove(), 320);
  }, 2600);
}

function buildCards() {
  for (const type of TOWER_ORDER) {
    const def = TOWERS[type];
    const card = document.createElement('button');
    card.className = 'tower-card';
    card.dataset.type = type;
    card.setAttribute('role', 'listitem');
    card.setAttribute('aria-label', `${def.name}, ${def.cost} credits`);
    card.title = `${def.name} — ${def.cost} credits\n${def.desc}\nDrag onto the map or tap, then tap the sand.`;
    card.innerHTML = `
      <span class="hotkey">${def.hotkey}</span>
      <span class="tower-icon">${def.icon}</span>
      <span class="tower-name">${def.short}</span>
      <span class="cost">${COIN}${def.cost}</span>
    `;
    card.addEventListener('pointerdown', (e) => onCardDown(e, type, card));
    towerList.appendChild(card);
  }
}

function setArmed(type) {
  for (const el of towerList.children) el.classList.toggle('armed', el.dataset.type === type);
  activeCard = type ? [...towerList.children].find(el => el.dataset.type === type) : null;
  placeHint.classList.toggle('hidden', !type);
}

function cancelPlacement(silent = false) {
  if (!game.pendingType && !selectedType) return;
  game.setPending(null);
  game.setPreview(null);
  selectedType = null;
  setArmed(null);
  dragGhost.classList.add('hidden');
  ghostVisible = false;
  if (!silent) audio.ui();
}

/* ---------------- drag & drop ---------------- */

let drag = null;

function onCardDown(e, type, card) {
  if (e.button !== undefined && e.button !== 0) return;
  if (!game.started) return;
  if (game.phase === 'victory' || game.phase === 'defeat') return;
  e.preventDefault();
  audio.ensure();
  const def = TOWERS[type];
  if (game.credits < def.cost) {
    audio.error();
    toast(`Need ${def.cost - game.credits} more credits for ${def.short}`, 'bad');
    return;
  }
  drag = {
    type,
    card,
    startX: e.clientX,
    startY: e.clientY,
    moved: false,
    pointerId: e.pointerId,
    captured: false,
  };
  try {
    card.setPointerCapture(e.pointerId);
    drag.captured = true;
  } catch {}
}

window.addEventListener('pointermove', (e) => {
  if (!drag) return;
  if (!drag.moved) {
    const dx = e.clientX - drag.startX;
    const dy = e.clientY - drag.startY;
    if (Math.hypot(dx, dy) < 7) return;
    drag.moved = true;
    audio.ensure();
    // close inspector + arm the tower
    closeInspector(true);
    if (selectedType) cancelPlacement(true);
    selectedType = drag.type;
    game.setPending(drag.type);
    setArmed(drag.type);
    drag.card.classList.add('dragging');
    dragGhost.innerHTML = `
      <span class="tower-icon">${TOWERS[drag.type].icon}</span>
      <span class="ghost-name">${TOWERS[drag.type].short}</span>
      <span class="ghost-cost">${COIN}${TOWERS[drag.type].cost}</span>`;
    dragGhost.classList.remove('hidden');
    dragGhost.classList.remove('bad');
    ghostVisible = true;
    audio.ui();
  }
  if (!drag.moved) return;
  dragGhost.style.left = `${e.clientX}px`;
  dragGhost.style.top = `${e.clientY}px`;
  const pos = pointToMap(e.clientX, e.clientY);
  if (pos.inside) {
    game.setPreview(pos.nx, pos.ny);
    const valid = game.preview?.valid ?? false;
    dragGhost.classList.toggle('bad', !valid);
    placeHint.classList.add('hidden');
  } else {
    game.setPreview(null);
    dragGhost.classList.remove('bad');
  }
});

window.addEventListener('pointerup', (e) => {
  if (!drag) return;
  const d = drag;
  drag = null;
  try { if (d.captured && d.card.hasPointerCapture(d.pointerId)) d.card.releasePointerCapture(d.pointerId); } catch {}
  d.card.classList.remove('dragging');
  dragGhost.classList.add('hidden');
  ghostVisible = false;

  if (!d.moved) {
    // tap on the card → arm placement for the next map tap
    if (selectedType === d.type) {
      cancelPlacement();
    } else {
      closeInspector(true);
      game.setPending(d.type);
      selectedType = d.type;
      setArmed(d.type);
      audio.ui();
      toast(`Tap the sand to deploy ${TOWERS[d.type].short}`);
    }
    return;
  }

  const pos = pointToMap(e.clientX, e.clientY);
  let placed = false;
  let reason = '';
  if (pos.inside) {
    const res = game.placeTower(d.type, pos.nx, pos.ny);
    placed = res.ok;
    reason = res.reason;
  }
  game.setPending(null);
  game.setPreview(null);
  selectedType = null;
  setArmed(null);
  if (placed) {
    const t = game.towers[game.towers.length - 1];
    toast(`${TOWERS[d.type].name} deployed`, 'good');
    if (t) selectTower(t, true);
  } else if (pos.inside && reason) {
    audio.error();
    toast(reason, 'bad');
  }
  syncUI(true);
});

window.addEventListener('pointercancel', () => {
  if (!drag) return;
  const card = drag.card;
  drag = null;
  card.classList.remove('dragging');
  dragGhost.classList.add('hidden');
  game.setPending(null);
  game.setPreview(null);
  selectedType = null;
  setArmed(null);
});

/* ---------------- map input ---------------- */

canvas.addEventListener('contextmenu', (e) => e.preventDefault());

canvas.addEventListener('pointerdown', (e) => {
  if (!game.started) return;
  if (game.phase === 'victory' || game.phase === 'defeat') return;
  if (e.button !== undefined && e.button !== 0) return;
  audio.ensure();
  const pos = pointToMap(e.clientX, e.clientY);
  if (!pos.inside) return;

  if (game.pendingType) {
    e.preventDefault();
    const type = game.pendingType;
    const res = game.placeTower(type, pos.nx, pos.ny);
    if (res.ok) {
      game.setPending(null);
      game.setPreview(null);
      selectedType = null;
      setArmed(null);
      toast(`${TOWERS[type].name} deployed`, 'good');
      const t = game.towers[game.towers.length - 1];
      if (t) selectTower(t, true);
    } else {
      audio.error();
      toast(res.reason || 'Cannot build there', 'bad');
    }
    syncUI(true);
    return;
  }

  const tower = game.towerAt(pos.px, pos.py);
  if (tower) {
    selectTower(tower);
    audio.ui();
  } else {
    closeInspector();
    game.selectTower(null);
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!game.pendingType) return;
  const pos = pointToMap(e.clientX, e.clientY);
  if (pos.inside) game.setPreview(pos.nx, pos.ny);
  else game.setPreview(null);
});

canvas.addEventListener('pointerleave', () => {
  if (game.pendingType) game.setPreview(null);
});

/* ---------------- inspector ---------------- */

function selectTower(tower, quiet = false) {
  if (!tower) return;
  game.selectTower(tower);
  selectedType = null;
  setArmed(null);
  game.setPreview(null);
  buildPanel.classList.add('hidden');
  inspectPanel.classList.remove('hidden');
  refreshInspector();
  if (!quiet) audio.ui();
}

function closeInspector(quiet = false) {
  if (inspectPanel.classList.contains('hidden') && !game.selected) return;
  inspectPanel.classList.add('hidden');
  buildPanel.classList.remove('hidden');
  game.selectTower(null);
  if (!quiet) audio.ui();
}

function refreshInspector() {
  const t = game.selected;
  if (!t) { closeInspector(true); return; }
  const def = TOWERS[t.type];
  const lv = towerLevel(t.type, t.level);
  $('#inspectIcon').innerHTML = def.icon;
  $('#inspectName').textContent = def.name;
  $('#inspectLevel').textContent = `LEVEL ${t.level} / 4  ·  ${def.role}`;
  $('#inspectDesc').textContent = def.desc;
  $('#statDamage').textContent = lv.damage % 1 === 0 ? lv.damage : lv.damage.toFixed(1);
  $('#statRange').textContent = Math.round(lv.range);
  $('#statRate').textContent = `${(1 / lv.cooldown).toFixed(1)}/s`;
  const mode = TARGET_MODES.find(m => m.id === t.mode) || TARGET_MODES[0];
  $('#targetMode').textContent = mode.label;
  $('#targetBtn').title = `Priority: ${mode.desc}. Tap to change.`;
  const up = $('#upgradeBtn');
  if (lv.nextLevel) {
    up.classList.remove('maxed');
    up.classList.toggle('disabled', game.credits < lv.upgrade);
    up.querySelector('.up-label').textContent = `UPGRADE TO LEVEL ${lv.nextLevel}`;
    up.querySelector('.up-cost').innerHTML = `${COIN}<b id="upgradeCost">${fmt(lv.upgrade)}</b>`;
    $('#upgradeDelta').textContent = lv.note;
    up.title = `Upgrade for ${lv.upgrade} credits: ${lv.note}`;
  } else {
    up.classList.add('maxed');
    up.classList.remove('disabled');
    up.querySelector('.up-label').textContent = 'ELITE TIER REACHED';
    up.querySelector('.up-cost').innerHTML = '<b>MAX</b>';
    $('#upgradeDelta').textContent = 'This tower is fully upgraded';
    up.title = 'Fully upgraded';
  }
  $('#sellValue').textContent = fmt(sellValue(t));
}

function syncInspectorAffordability() {
  const t = game.selected;
  if (!t) return;
