/* ---------------- HUD / wave ---------------- */

let lastHud = { credits: -1, lives: -1, wave: -1, started: false };

function syncUI(force = false) {
  if (!game) return;
  const h = game.hud();

  const creditsEl = $('#credits');
  const livesEl = $('#lives');
  if (force || h.credits !== lastHud.credits) {
