  $('#waveSub').textContent = h.phase === 'wave' ? `${h.alive + h.queue} hostiles` : h.phase === 'build' ? (h.wave > 1 ? 'Build phase' : 'Prepare defenses') : h.phase === 'victory' ? 'Relay held' : 'Relay lost';
  $('#waveProgress').style.width = `${(h.phase === 'wave' ? h.progress : 0) * 100}%`;

