function setPaused(paused) {
  if (!game.started) return;
  if (game.phase === 'victory' || game.phase === 'defeat') return;
  game.paused = paused;
  pauseModal.classList.toggle('hidden', !paused);
  if (paused) {
    cancelPlacement(true);
