$('#cancelPlace').addEventListener('click', () => cancelPlacement());

/* ---------------- start / end screens ---------------- */

let runFinished = false;

function startGame(auto = false) {
  audio.ensure();
  startScreen.classList.add('hidden');
  game.begin();
  closeInspector(true);
  syncUI(true);
  if (!auto) {
    audio.ui();
