async page => {
  await page.evaluate(() => { __game.credits = 5000; __game.waveNumber = 8; });
  const chosen = await page.evaluate(() => {
    const g = __game;
    const types = ['scout', 'scout', 'ion', 'rocket', 'laser', 'jedi', 'bounty'];
    const placed = [];
    const dists = [0, 42, 14, 26, 38, 54, 74];
    for (let i = 0; i < types.length; i++) {
      let best = null;
      let bestScore = Infinity;
      for (let y = 0.12; y < 0.94; y += 0.02) {
        for (let x = 0.05; x < 0.95; x += 0.015) {
          if (!g.canPlace(types[i], x, y).ok) continue;
          let spacing = Infinity;
          for (const p of placed) spacing = Math.min(spacing, Math.hypot(p.x - x, p.y - y));
          if (spacing < 0.15) continue;
          const d = g.distanceToPath(x * g.w, y * g.h);
          const clearance = g.pathWidth() / 2 + 26 * g.S;
          const want = clearance + dists[i] * g.S;
          const score = Math.abs(d - want) + Math.max(0, 0.26 - spacing) * 300;
          if (score < bestScore) { bestScore = score; best = { x, y }; }
        }
      }
      if (best) {
        const res = g.placeTower(types[i], best.x, best.y);
        if (res.ok) placed.push({ ...best, type: types[i], id: res.tower.id });
      }
    }
    // upgrade all towers to level 3 for a livelier demo
    for (const t of g.towers) {
      g.selectTower(t);
      g.credits += 800;
      g.upgradeSelected();
      g.upgradeSelected();
    }
    g.selectTower(null);
    g.credits = 1475;
    return placed;
  });
  await page.waitForTimeout(300);
  await page.click('#nextWaveBtn');
  await page.waitForTimeout(10500);
  const info = await page.evaluate(() => ({ enemies: __game.enemies.length, towers: __game.towers.length, wave: __game.waveNumber, phase: __game.phase, lives: __game.lives, credits: __game.credits, kills: __game.kills, boss: __game.bossInfo(), speed: __game.speed, projectiles: __game.projectiles.length, particles: __game.particles.length }));
  return { chosen, info };
}

