import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const OUT = '/home/runner/work/Star-Wars-Tower-Defense/Star-Wars-Tower-Defense/screenshots';
const URL = 'http://localhost:3002/?play=1';
const errors = [];
const log = (...a) => console.log(...a);

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
page.setDefaultTimeout(15000);
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('requestfailed', r => errors.push('requestfailed: ' + r.url() + ' ' + (r.failure()?.errorText || '')));

await page.goto(URL, { waitUntil: 'load' });
await page.waitForFunction(() => window.__game && window.__game.started, null, { timeout: 15000 });
await page.waitForTimeout(900);

log('viewport', await page.evaluate(() => ({ stage: [window.__game.w, window.__game.h], S: window.__game.S, credits: window.__game.credits, shop: document.querySelector('#shop').getBoundingClientRect().width })));
await page.screenshot({ path: `${OUT}/final-mobile-idle.png` });

/* --- UI drag a tower from the shop onto the map --- */
const scout = page.locator('.tower-card[data-type="scout"]');
const cardBox = await scout.boundingBox();
const spot = await page.evaluate(() => {
  const g = window.__game;
  const r = g.canvas.getBoundingClientRect();
  const candidates = [[0.42, 0.44], [0.48, 0.50], [0.36, 0.48], [0.52, 0.44], [0.30, 0.50]];
  for (const [x, y] of candidates) {
    if (g.canPlace('scout', x, y).ok) return { x, y, left: r.left + x * r.width, top: r.top + y * r.height };
  }
  return null;
});
log('drag spot', spot);
await page.mouse.move(cardBox.x + cardBox.width / 2, cardBox.y + cardBox.height / 2);
await page.mouse.down();
await page.mouse.move(spot.left - 80, spot.top + 20, { steps: 6 });
await page.mouse.move(spot.left, spot.top, { steps: 8 });
await page.mouse.up();
await page.waitForTimeout(400);
log('after drag towers/credits', await page.evaluate(() => ({ towers: window.__game.towers.map(t => t.type), credits: window.__game.credits, pending: window.__game.pendingType })));

/* --- tap-to-place another tower --- */
const scoutCard = await scout.boundingBox();
await page.mouse.click(scoutCard.x + scoutCard.width / 2, scoutCard.y + scoutCard.height / 2);
const spot2 = await page.evaluate(() => {
  const g = window.__game;
  const r = g.canvas.getBoundingClientRect();
  for (const [x, y] of [[0.55, 0.55], [0.62, 0.48], [0.45, 0.62], [0.34, 0.62]]) {
    if (g.canPlace('scout', x, y).ok) return { left: r.left + x * r.width, top: r.top + y * r.height };
  }
  return null;
});
if (spot2) {
  await page.mouse.click(spot2.left, spot2.top);
  await page.waitForTimeout(300);
}
log('after tap towers', await page.evaluate(() => window.__game.towers.map(t => t.type)));

/* --- seed a visually complete defense, including every tower type --- */
const seeded = await page.evaluate(() => {
  const g = window.__game;
  g.credits = 50000;
  const types = ['scout', 'ion', 'rocket', 'laser', 'jedi', 'bounty'];
  const added = [];
  const spots = [];
  for (let y = 0.10; y <= 0.90; y += 0.025) {
    for (let x = 0.05; x <= 0.90; x += 0.025) {
      if (g.canPlace('scout', x, y).ok) spots.push({ x, y });
    }
  }
  // place near the path, spread along it
  const path = g.pathPts;
  spots.sort((a, b) => {
    const da = Math.min(...path.filter((_, i) => i % 15 === 0).map(p => Math.hypot(p[0] - a.x * g.w, p[1] - a.y * g.h)));
    const db = Math.min(...path.filter((_, i) => i % 15 === 0).map(p => Math.hypot(p[0] - b.x * g.w, p[1] - b.y * g.h)));
    return da - db;
  });
  let i = 0;
  for (const type of types) {
    let placed = false;
    for (let n = 0; n < spots.length && !placed; n++) {
      const s = spots[(i + n * 7) % spots.length];
      if (!g.canPlace(type, s.x, s.y).ok) continue;
      const res = g.placeTower(type, s.x, s.y);
      if (res.ok) {
        added.push(type);
        i = (i + n * 7) % spots.length + 5;
        placed = true;
      }
    }
  }
  // upgrade a couple of towers
  for (let n = 0; n < Math.min(3, g.towers.length); n++) {
    g.selectTower(g.towers[n]);
    g.upgradeSelected();
    g.upgradeSelected();
  }
  g.selectTower(null);
  g.credits = 1250;
  return { added, towers: g.towers.map(t => ({ type: t.type, level: t.level, x: t.x, y: t.y })) };
});
log('seeded', JSON.stringify(seeded));
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/final-mobile-defense.png` });

/* --- combat --- */
await page.click('#nextWaveBtn');
await page.waitForTimeout(2600);
const combat = await page.evaluate(() => {
  const g = window.__game;
  return { wave: g.waveNumber, phase: g.phase, spawned: g.waveSpawned, total: g.waveTotal, enemies: g.enemies.length, projectiles: g.projectiles.length, kills: g.kills, lives: g.lives };
});
log('combat', JSON.stringify(combat));
await page.screenshot({ path: `${OUT}/final-mobile-combat.png` });

/* --- inspector + upgrade + sell --- */
await page.evaluate(() => { window.__game.selected = null; window.__game.speed = 1; });
const tower = await page.evaluate(() => {
  const g = window.__game;
  const t = g.towers.find(t => t.type === 'laser') || g.towers[0];
  const r = g.canvas.getBoundingClientRect();
  return { type: t.type, level: t.level, left: r.left + t.x, top: r.top + t.y };
});
await page.mouse.click(tower.left, tower.top);
await page.waitForTimeout(350);
log('inspector visible', await page.evaluate(() => !document.querySelector('#inspectPanel').classList.contains('hidden')));
await page.screenshot({ path: `${OUT}/final-mobile-inspector.png` });
const beforeUp = await page.evaluate(() => window.__game.selected?.level);
await page.click('#upgradeBtn');
await page.waitForTimeout(250);
const afterUp = await page.evaluate(() => ({ level: window.__game.selected?.level, credits: window.__game.credits }));
log('upgrade', beforeUp, '->', JSON.stringify(afterUp));
const beforeSell = await page.evaluate(() => ({ towers: window.__game.towers.length, credits: window.__game.credits }));
await page.click('#sellBtn');
await page.waitForTimeout(250);
const afterSell = await page.evaluate(() => ({ towers: window.__game.towers.length, credits: window.__game.credits }));
log('sell', JSON.stringify(beforeSell), '->', JSON.stringify(afterSell));

/* --- pause modal --- */
await page.click('#btnPause');
await page.waitForTimeout(250);
log('paused', await page.evaluate(() => ({ paused: window.__game.paused, modal: !document.querySelector('#pauseModal').classList.contains('hidden') })));
await page.screenshot({ path: `${OUT}/final-mobile-pause.png` });
await page.click('#resumeBtn');
await page.waitForTimeout(200);

/* --- defeat / end screen --- */
await page.evaluate(() => window.__game.defeat());
await page.waitForTimeout(900);
log('end screen', await page.evaluate(() => ({ shown: !document.querySelector('#endScreen').classList.contains('hidden'), title: document.querySelector('#endTitle').textContent })));
await page.screenshot({ path: `${OUT}/final-mobile-end.png` });
await page.click('#againBtn');
await page.waitForTimeout(500);
log('restart', await page.evaluate(() => ({ started: window.__game.started, phase: window.__game.phase, towers: window.__game.towers.length, credits: window.__game.credits, wave: window.__game.waveNumber })));

/* --- desktop viewport --- */
await page.setViewportSize({ width: 1280, height: 720 });
await page.waitForTimeout(700);
const desk = await page.evaluate(() => {
  const g = window.__game;
  g.credits = 50000;
  const types = ['scout', 'ion', 'rocket', 'laser', 'jedi', 'bounty'];
  const spots = [];
  for (let y = 0.10; y <= 0.90; y += 0.02) for (let x = 0.04; x <= 0.92; x += 0.02) if (g.canPlace('scout', x, y).ok) spots.push({ x, y });
  let i = 0;
  for (const type of types) {
    for (let n = 0; n < spots.length; n++) {
      const s = spots[(i + n * 13) % spots.length];
      if (g.canPlace(type, s.x, s.y).ok) { g.placeTower(type, s.x, s.y); i = (i + 37) % spots.length; break; }
    }
  }
  g.credits = 1250;
  g.selectTower(null);
  return { towers: g.towers.length, w: g.w, h: g.h };
});
log('desktop', JSON.stringify(desk));
await page.waitForTimeout(400);
await page.screenshot({ path: `${OUT}/final-desktop.png` });

/* --- title screen, desktop and landscape mobile --- */
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(700);
await page.screenshot({ path: `${OUT}/final-desktop-title.png` });
await page.setViewportSize({ width: 844, height: 390 });
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/final-mobile-title.png` });

log('errors', JSON.stringify(errors));
