import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, deviceScaleFactor: 2 });
page.on('pageerror', e => console.log('PAGEERROR', e.stack?.split('\n').slice(0, 4).join('\n')));
await page.addInitScript(() => {
  window.__nan = [];
  const orig = CanvasRenderingContext2D.prototype.createRadialGradient;
  CanvasRenderingContext2D.prototype.createRadialGradient = function (...args) {
    if (args.some(v => typeof v === 'number' && !Number.isFinite(v))) {
      const g = window.__game;
      const bad = (g?.effects || []).filter(f => !Number.isFinite(f.r) || !Number.isFinite(f.maxR) || !Number.isFinite(f.max) || !Number.isFinite(f.life)).slice(0, 3);
      window.__nan.push({ args: args.map(v => String(v)), callStack: new Error().stack, bad });
      if (window.__nan.length > 4) return orig.apply(this, [0, 0, 0, 0, 0, 1]);
    }
    return orig.apply(this, args);
  };
});
await page.goto('http://localhost:3002/?play=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__game?.started);
await page.evaluate(() => {
  const g = window.__game;
  g.credits = 99999;
  const spots = [];
  for (let y = 0.14; y <= 0.86; y += 0.03) for (let x = 0.07; x <= 0.88; x += 0.03) if (g.canPlace('scout', x, y).ok) spots.push({ x, y });
  const near = spots.filter(p => g.distanceToPath(p.x * g.w, p.y * g.h) < 96).sort((a, b) => a.y - b.y || a.x - b.x);
  const types = ['scout', 'scout', 'scout', 'scout', 'ion', 'ion', 'rocket', 'rocket', 'laser', 'laser', 'jedi', 'bounty'];
  let ti = 0;
  for (const p of near) { if (ti >= types.length) break; if (g.canPlace(types[ti], p.x, p.y).ok) { g.placeTower(types[ti], p.x, p.y); ti++; } }
  for (const t of g.towers.slice(0, 4)) { g.selectTower(t); g.upgradeSelected(); g.upgradeSelected(); }
  g.selectTower(null);
  g.waveNumber = 8;
  g.speed = 2;
  g.startWave();
});
await page.waitForTimeout(7000);
console.log(JSON.stringify(await page.evaluate(() => window.__nan.slice(0, 2)), null, 2));
await browser.close();

