import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 844, height: 390 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/?play=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__game?.started);
const result = await page.evaluate(() => {
  const g = window.__game;
  g.credits = 1e6;
  const spots = [];
  for (let y = 0.2; y <= 0.8; y += 0.04) for (let x = 0.1; x <= 0.85; x += 0.04) if (g.canPlace('scout', x, y).ok) spots.push({ x, y });
  const out = {};
  let si = 0;
  for (const type of ['scout', 'ion', 'rocket', 'laser', 'jedi', 'bounty']) {
    let tower;
    for (let n = 0; n < spots.length; n++) {
      const s = spots[(si + n) % spots.length];
      const res = g.placeTower(type, s.x, s.y);
      if (res.ok) { tower = res.tower; si = (si + n + 11) % spots.length; break; }
    }
    if (!tower) { out[type] = 'could not place'; continue; }
    const levels = [];
    g.selectTower(tower);
    for (let l = 1; l <= 4; l++) {
      levels.push({ level: tower.level, splash: tower.splash, slow: tower.slow, slowDuration: tower.slowDuration, chain: tower.chain, range: tower.range, damage: tower.damage });
      if (l < 4) {
        const up = g.upgradeSelected();
        if (!up.ok) levels.push({ upgradeError: up.reason });
      }
    }
    out[type] = levels;
    g.selectTower(null);
  }
  // rocket splash sanity
  const rocket = g.towers.find(t => t.type === 'rocket');
  out.rocketFinalSplash = rocket?.splash;
  return out;
});
console.log(JSON.stringify(result, null, 1));
console.log('errors', errors);
await browser.close();

