const result = await page.evaluate(() => {
  const g = window.__game;
  g.paused = true; // stop rAF simulation while we step manually
  g.credits = 1e6;
  const spots = [];
  for (let y = 0.08; y <= 0.92; y += 0.022) for (let x = 0.05; x <= 0.9; x += 0.022) if (g.canPlace('scout', x, y).ok) spots.push({ x, y });
  const near = spots
    .map(p => ({ ...p, d: g.distanceToPath(p.x * g.w, p.y * g.h) }))
    .filter(p => p.d < 78)
    .sort((a, b) => b.d - a.d);
  const types = ['scout', 'ion', 'rocket', 'laser', 'jedi', 'bounty'];
  let ti = 0;
  for (const p of near) {
    const type = types[ti % types.length];
    if (g.canPlace(type, p.x, p.y).ok) {
      g.placeTower(type, p.x, p.y);
      ti++;
    }
    if (ti >= 30) break;
  }
  for (const t of g.towers) {
    g.selectTower(t);
    g.upgradeSelected();
    g.upgradeSelected();
    g.upgradeSelected();
  }
  g.selectTower(null);
  g.lives = 5000;
  g.credits = 1e6;
  const waves = [];
  let renders = 0;
  let victory = false;
  for (let w = 1; w <= 25; w++) {
    g.waveNumber = w;
    g.phase = 'build';
    g.waveActive = false;
    g.spawnQueue = null;
    g.startWave();
    let steps = 0;
    while (g.waveActive && g.phase === 'wave' && steps < 4000) {
      g.update(0.15);
      steps++;
      if (steps % 7 === 0) { g.render(); renders++; }
    }
    waves.push({ wave: w, steps, kills: g.kills, lives: g.lives, phase: g.phase, enemies: g.enemies.length });
    if (g.phase === 'victory') { victory = true; break; }
  }
  g.render();
  return { towerCount: g.towers.length, renders, victory, phase: g.phase, kills: g.kills, creditsEarned: g.creditsEarned, lives: g.lives, waves };
});
console.log(JSON.stringify(result, null, 1));
console.log('errors', errors);
await browser.close();

