.menu-head .menu-back { justify-self: start; }
.menu-heading { display: flex; flex-direction: column; align-items: center; text-align: center; }
.menu-heading .start-eyebrow { margin: 0 0 2px; font-size: 6px; gap: 7px; }
.menu-heading .start-eyebrow span { width: 20px; }
.menu-heading h1 {
