  background: #0b111b;
  text-align: left;
  transition: transform 0.16s, border-color 0.16s, box-shadow 0.16s;
}
.map-tile-available:hover,
.map-tile-available:focus-visible {
  transform: translateY(-3px);
  border-color: rgba(241, 199, 111, 0.55);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.36), 0 0 0 1px rgba(241, 199, 111, 0.12) inset;
}
.map-tile-locked { opacity: 0.58; filter: saturate(0.48); cursor: not-allowed; }
.map-art {
  position: relative;
  display: block;
  height: clamp(58px, 16vh, 124px);
  overflow: hidden;
  background: #111827;
}
.m-ridge { position: absolute; left: 0; right: 0; bottom: -1px; display: block; height: 46%; }
.m-ridge-back { height: 62%; opacity: 0.72; }
.m-sun { position: absolute; border-radius: 50%; }
.m-sun-a {
  width: 31%;
  aspect-ratio: 1;
  left: 11%;
  top: 17%;
  background: radial-gradient(circle, #fff4cb 0 27%, #ffcf7c 52%, rgba(255, 180, 90, 0) 72%);
}
.m-sun-b {
  width: 17%;
  aspect-ratio: 1;
  left: 36%;
  top: 12%;
  background: radial-gradient(circle, #fff9e8 0 32%, #ffd691 60%, rgba(255, 196, 107, 0) 74%);
  opacity: 0.85;
}
.m-moon {
  position: absolute;
  width: 16%;
  aspect-ratio: 1;
  right: 18%;
  top: 14%;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 32%, #eaf1d8, #a8b98a 52%, #58664b 100%);
  box-shadow: 0 0 16px rgba(215, 235, 195, 0.18);
}
.art-tatooine { background: linear-gradient(180deg, #2b1c35 0%, #5d2f2e 42%, #c4763c 72%, #e0a95f 100%); }
