.art-hoth { background: linear-gradient(180deg, #08111d, #16283b 46%, #7893a3 82%, #cfe5ea); }
.art-hoth .m-sun-a { left: 69%; top: 12%; width: 18%; background: radial-gradient(circle, #f4fcff 0 34%, #b8dce8 64%, rgba(184, 220, 232, 0) 76%); }
.art-hoth .m-ridge { background: linear-gradient(180deg, #e1f2f6, #8fb2c0 72%, #63828f); clip-path: polygon(0 70%, 17% 28%, 33% 60%, 48% 18%, 66% 55%, 83% 32%, 100% 62%, 100% 100%, 0 100%); }
.art-hoth .m-ridge-back { background: #4e6d7c; clip-path: polygon(0 52%, 24% 18%, 46% 47%, 68% 12%, 87% 42%, 100% 28%, 100% 100%, 0 100%); }
.art-coruscant { background: radial-gradient(72% 110% at 52% 8%, #2c3855, #0a101a 70%); }
.art-coruscant .m-moon {
  width: 18%;
  right: 16%;
  top: 12%;
  background: radial-gradient(circle at 36% 34%, #ffd7a1, #c06f4d 48%, #502c30 100%);
  box-shadow: 0 0 18px rgba(255, 168, 100, 0.2);
}
.m-city {
  position: absolute;
  inset: auto 0 0;
  display: block;
  height: 58%;
  background: repeating-linear-gradient(90deg, #0b1119 0 7px, #1a2633 7px 11px, #0b1119 11px 17px);
  clip-path: polygon(0 55%, 6% 55%, 6% 28%, 11% 28%, 11% 45%, 17% 45%, 17% 16%, 21% 16%, 21% 50%, 29% 50%, 29% 35%, 34% 35%, 34% 60%, 42% 60%, 42% 20%, 48% 20%, 48% 42%, 55% 42%, 55% 12%, 60% 12%, 60% 36%, 68% 36%, 68% 55%, 75% 55%, 75% 26%, 82% 26%, 82% 48%, 90% 48%, 90% 18%, 95% 18%, 95% 44%, 100% 44%, 100% 100%, 0 100%);
}
