.art-endor .m-ridge-back { background: linear-gradient(180deg, #37553b, #142219); clip-path: polygon(0 55%, 11% 18%, 19% 54%, 31% 22%, 42% 58%, 55% 15%, 64% 52%, 78% 24%, 89% 55%, 100% 20%, 100% 100%, 0 100%); }
