.map-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: #6f705f;
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.1em;
}
.map-foot-badge { padding: 3px 7px; border: 1px solid rgba(241, 199, 111, 0.18); border-radius: 3px; color: #c4a86d; white-space: nowrap; }

.hangar-lead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: clamp(8px, 1.8vh, 15px) 0;
