  flex: none;
  padding: 4px 8px;
  border: 1px solid rgba(241, 199, 111, 0.35);
  border-radius: 5px;
  color: var(--gold);
  font-family: var(--font-head);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  transform: rotate(-4deg);
  white-space: nowrap;
  opacity: 0.9;
}
