  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: clamp(8px, 1vw, 12px) 6px;
  border: 1px solid rgba(241, 199, 111, 0.13);
  border-radius: 10px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.012));
  text-align: center;
}
.hangar-card-icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(241, 199, 111, 0.13);
  border-radius: 8px;
  background: rgba(241, 199, 111, 0.06);
  color: #f1d59b;
}
.hangar-card-icon svg { width: 30px; height: 30px; }
.hangar-card b { display: block; color: #f0e4d1; font-family: var(--font-head); font-size: 10px; letter-spacing: 0.06em; }
.hangar-card div span { display: block; margin-top: 1px; color: #8d806d; font-size: 5.3px; letter-spacing: 0.1em; }
.hangar-card em { color: var(--gold); font-size: 4.8px; font-style: normal; font-weight: 800; letter-spacing: 0.11em; opacity: 0.64; }
.hangar-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: clamp(8px, 1.7vh, 14px); }
.hangar-foot > span { color: #7b7364; font-size: 6px; font-weight: 800; letter-spacing: 0.12em; }
.hangar-foot .deploy-btn { padding: 8px 20px 7px; }

/* end screen */

