input.content:
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const OUT = '/home/runner/work/Star-Wars-Tower-Defense/Star-Wars-Tower-Defense/screenshots';
const errors = [];
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
page.setDefaultTimeout(10000);
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('requestfailed', r => errors.push('requestfailed: ' + r.url()));

const state = () => page.evaluate(() => {
  const vis = (id) => !document.getElementById(id).classList.contains('hidden');
  const box = (id) => {
    const r = document.getElementById(id).getBoundingClientRect();
    return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
  };
  return {
    screens: { start: vis('startScreen'), home: vis('homeScreen'), map: vis('mapScreen'), hangar: vis('hangarScreen') },
    started: window.__game.started,
    mapName: document.querySelector('.map-name').textContent.trim(),
    hubTowers: document.querySelectorAll('#hubTowerPreview .hub-mini-icon').length,
    roster: document.querySelectorAll('#hangarRoster .hangar-card').length,
    startTitle: document.querySelector('#startScreen h1').innerText.replace(/\n/g, ' '),
    viewport: [innerWidth, innerHeight],
    scroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
    hubBox: box('homeScreen'),
  };
});

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(800);
console.log('start', await state());
await page.screenshot({ path: `${OUT}/menu-mobile-start.png` });

await page.click('#playBtn');
await page.waitForTimeout(500);
console.log('home', await state());
await page.screenshot({ path: `${OUT}/menu-mobile-home.png` });

await page.click('#chooseMapBtn');
await page.waitForTimeout(500);
console.log('map', await state());
await page.screenshot({ path: `${OUT}/menu-mobile-map.png` });

await page.click('.map-tile-available');
await page.waitForTimeout(700);
console.log('game from map', await state());
await page.screenshot({ path: `${OUT}/menu-mobile-game.png` });

// Pause and jump to map selection
await page.click('#btnPause');
await page.waitForTimeout(250);
await page.click('#quitMapBtn');
await page.waitForTimeout(400);
console.log('quit to map', await state());

// Home -> upgrades -> home
await page.click('#mapBackBtn');
await page.waitForTimeout(300);
await page.click('#upgradesBtn');
await page.waitForTimeout(500);
console.log('hangar', await state());
await page.screenshot({ path: `${OUT}/menu-mobile-hangar.png` });
await page.click('#hangarBackBtn');
await page.waitForTimeout(300);
await page.click('#hubBackBtn');
await page.waitForTimeout(300);
console.log('back to start', await state());

// Desktop views
await page.setViewportSize({ width: 1280, height: 720 });
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/menu-desktop-start.png` });
await page.click('#playBtn');
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/menu-desktop-home.png` });
await page.click('#chooseMapBtn');
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/menu-desktop-map.png` });
await page.click('#mapBackBtn');
await page.waitForTimeout(300);
await page.click('#upgradesBtn');
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/menu-desktop-hangar.png` });

console.log('errors', errors);
await browser.close();
if (errors.length) process.exitCode = 2;

